INSERT INTO `travel_route` (`id`,`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES (1127,'婺源篁岭纯攻略·臻享版1','guide','江西 · 上饶','village','https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80',3990,1995,1,'晒秋人家 / 垒心桥 / 梯田花海 —— 深度攻略助你玩透婺源篁岭精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「婺源篁岭」两日慢旅行——古村落。婺源荷包红鲤鱼可真空打包带回家。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 上饶"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴上饶","description":"集合出发，大巴直达婺源篁岭，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"晒秋人家","description":"抵达后首游晒秋人家，晒秋最佳拍摄位在天街中层，上午顺光。","addr":"婺源县江湾镇篁岭村","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐蒸汽糕（人均28元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"垒心桥","description":"早起人少，垒心桥精华时段，桥面风大，手机拿稳。","addr":"篁岭景区索道上站","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐清明果，人均15元，补充体力。","addr":"篁岭古村巷内","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"梯田花海","description":"午后游览梯田花海，春季油菜花、秋季稻浪，两季都出片。","addr":"篁岭村北坡","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"晒秋人家","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"晒秋人家是婺源篁岭最有代表性的看点，晒秋最佳拍摄位在天街中层，上午顺光。攻略把它排进主线，时间留得最足。","notice":"晒秋最佳拍摄位在天街中层，上午顺光。这个点位上午光线最好。","durationMinutes":120,"addr":"婺源县江湾镇篁岭村"},{"spotId":"S2","name":"垒心桥","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"垒心桥是婺源篁岭最有代表性的看点，桥面风大，手机拿稳。攻略把它排进主线，时间留得最足。","notice":"桥面风大，手机拿稳。提前10分钟到，避开旅行团大部队。","durationMinutes":60,"addr":"篁岭景区索道上站"},{"spotId":"S3","name":"梯田花海","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"梯田花海是婺源篁岭最有代表性的看点，春季油菜花、秋季稻浪，两季都出片。攻略把它排进主线，时间留得最足。","notice":"春季油菜花、秋季稻浪，两季都出片。拍照记得留神脚下台阶。","durationMinutes":90,"addr":"篁岭村北坡"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"蒸汽糕（人均28元）","description":"上饶 · 婺源篁岭的招牌是蒸汽糕，天街食府本地人都认这家，点单照攻略不踩雷。","addr":"篁岭天街中段"},{"title":"清明果（人均15元）","description":"上饶 · 婺源篁岭的招牌是清明果，晒秋人家小吃铺本地人都认这家，点单照攻略不踩雷。","addr":"篁岭古村巷内"},{"title":"荷包红鲤鱼（人均68元）","description":"上饶 · 婺源篁岭的招牌是荷包红鲤鱼，篁岭酒楼本地人都认这家，点单照攻略不踩雷。","addr":"篁岭村口第一家"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1795,"required":false},{"name":"住宿参考","amount":1396,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["换洗衣物与外套（早晚温差）","少量零食补给","相机或运动相机","常用药品（肠胃药/创可贴）","身份证件与手机充电宝","防晒霜与遮阳帽","轻便雨衣或折叠伞","墨镜与拍照道具"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["山区信号弱，提前下载离线地图","恶劣天气听从景区安排，不进入未开放区域","高原地区避免剧烈运动，备好氧气瓶","看好同行老人小孩，走失原地等待"],"faqs":[["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["当地有什么必吃？","到了 上饶，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"]]}',2,'这一程，山水都在替你说话。','on');
INSERT INTO `travel_route` (`id`,`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES (1128,'三清山纯攻略·臻享版2','guide','江西 · 上饶','mountain','https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80',3990,1995,2,'南清园 / 阳光海岸 / 万寿园 —— 深度攻略助你玩透三清山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「三清山」三日深度游——山岳。三清山猴头菇干货是手信首选。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 上饶"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往上饶，抵达后办理入住、熟悉周边环境。","addr":"上饶市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"南清园","description":"下午首站南清园，调整状态进入旅行节奏，巨蟒出山、东方女神都在这条环线，台阶多备水。","addr":"三清山风景区南门","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游上饶一带氛围拉满，晚餐石鸡汤锅人均58元。","addr":"三清山外双溪服务区","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"阳光海岸","description":"全天主景点阳光海岸，栈道悬空，恐高走东线缓冲段。","addr":"三清山高空栈道","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐野艾果（人均10元），早点休息。","addr":"南山索道下站旁","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"万寿园","description":"收官万寿园，坡缓树多，适合收尾慢慢走。","addr":"三清山南部入口","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐三清山烧饼后集合返程，三日旅程圆满。","addr":"登山途中补给站","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"南清园","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"南清园是三清山最有代表性的看点，巨蟒出山、东方女神都在这条环线，台阶多备水。攻略把它排进主线，时间留得最足。","notice":"巨蟒出山、东方女神都在这条环线，台阶多备水。周边有休息区与补给点，随时停留。","durationMinutes":240,"addr":"三清山风景区南门"},{"spotId":"S2","name":"阳光海岸","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"阳光海岸是三清山最有代表性的看点，栈道悬空，恐高走东线缓冲段。攻略把它排进主线，时间留得最足。","notice":"栈道悬空，恐高走东线缓冲段。这个点位上午光线最好。","durationMinutes":150,"addr":"三清山高空栈道"},{"spotId":"S3","name":"万寿园","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"万寿园是三清山最有代表性的看点，坡缓树多，适合收尾慢慢走。攻略把它排进主线，时间留得最足。","notice":"坡缓树多，适合收尾慢慢走。这个点位上午光线最好。","durationMinutes":90,"addr":"三清山南部入口"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"石鸡汤锅（人均58元）","description":"上饶 · 三清山的招牌是石鸡汤锅，山脚农家菜本地人都认这家，点单照攻略不踩雷。","addr":"三清山外双溪服务区"},{"title":"野艾果（人均10元）","description":"上饶 · 三清山的招牌是野艾果，路边农家本地人都认这家，点单照攻略不踩雷。","addr":"南山索道下站旁"},{"title":"三清山烧饼（人均8元）","description":"上饶 · 三清山的招牌是三清山烧饼，南清园补给点本地人都认这家，点单照攻略不踩雷。","addr":"登山途中补给站"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1795,"required":false},{"name":"住宿参考","amount":1396,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["轻便雨衣或折叠伞","舒适徒步鞋（防滑鞋底）","相机或运动相机","换洗衣物与外套（早晚温差）","墨镜与拍照道具","保温水杯与少量现金","少量零食补给","身份证件与手机充电宝"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["贵重物品随身携带，景区人多注意","涉水项目穿好救生衣，听从工作人员安排","高原地区避免剧烈运动，备好氧气瓶","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["几月份去 上饶 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["到达 上饶 的交通方便吗？","推荐先到 上饶，再打车或景区直通车前往核心景区；自驾导航直接搜三清山即可。"]]}',2,'出发这一刻，惊喜已经在路上。','on');
INSERT INTO `travel_route` (`id`,`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES (1129,'武功山纯攻略·臻享版3','guide','江西 · 萍乡','mountain','https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80',3990,1995,2,'金顶 / 发云界 / 玻璃栈道 —— 深度攻略助你玩透武功山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「武功山」两日慢旅行——山岳。武功山泉水豆腐宴别错过。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 萍乡"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴萍乡","description":"集合出发，大巴直达武功山，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"金顶","description":"抵达后首游金顶，日出云海核心位，山顶比山下冷10度。","addr":"武功山风景区金顶","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐萍乡小炒肉（人均42元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"发云界","description":"早起人少，发云界精华时段，高山草甸连绵，徒步精华段。","addr":"武功山发云界段","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐艾米古，人均10元，补充体力。","addr":"金顶驿站","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"玻璃栈道","description":"午后游览玻璃栈道，栈道限流，旺季排30分钟。","addr":"武功山吊马桩","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"金顶","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"金顶是武功山最有代表性的看点，日出云海核心位，山顶比山下冷10度。攻略把它排进主线，时间留得最足。","notice":"日出云海核心位，山顶比山下冷10度。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"武功山风景区金顶"},{"spotId":"S2","name":"发云界","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"发云界是武功山最有代表性的看点，高山草甸连绵，徒步精华段。攻略把它排进主线，时间留得最足。","notice":"高山草甸连绵，徒步精华段。提前10分钟到，避开旅行团大部队。","durationMinutes":240,"addr":"武功山发云界段"},{"spotId":"S3","name":"玻璃栈道","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"玻璃栈道是武功山最有代表性的看点，栈道限流，旺季排30分钟。攻略把它排进主线，时间留得最足。","notice":"栈道限流，旺季排30分钟。这个点位上午光线最好。","durationMinutes":60,"addr":"武功山吊马桩"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"萍乡小炒肉（人均42元）","description":"萍乡 · 武功山的招牌是萍乡小炒肉，山脚菜馆本地人都认这家，点单照攻略不踩雷。","addr":"武功山游客中心旁"},{"title":"艾米古（人均10元）","description":"萍乡 · 武功山的招牌是艾米古，山上补给点本地人都认这家，点单照攻略不踩雷。","addr":"金顶驿站"},{"title":"紫红米粉（人均15元）","description":"萍乡 · 武功山的招牌是紫红米粉，萍乡米粉店本地人都认这家，点单照攻略不踩雷。","addr":"武功山镇主街"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1795,"required":false},{"name":"住宿参考","amount":1396,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["换洗衣物与外套（早晚温差）","防晒霜与遮阳帽","保温水杯与少量现金","墨镜与拍照道具","身份证件与手机充电宝","相机或运动相机","少量零食补给","舒适徒步鞋（防滑鞋底）"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["涉水项目穿好救生衣，听从工作人员安排","夜间出行结伴，走主路不抄小道","看好同行老人小孩，走失原地等待","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["当地有什么必吃？","到了 萍乡，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"]]}',2,'把日常调成静音，听风与远方的声音。','on');
INSERT INTO `travel_route` (`id`,`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES (1130,'井冈山纯攻略·臻享版4','guide','江西 · 吉安','red','https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80',3990,1995,7,'黄洋界 / 茨坪革命旧址群 / 龙潭 —— 深度攻略助你玩透井冈山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「井冈山」三日深度游——人文。井冈山竹制工艺品轻便好带。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 吉安"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往吉安，抵达后办理入住、熟悉周边环境。","addr":"吉安市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"黄洋界","description":"下午首站黄洋界，调整状态进入旅行节奏，保卫战旧址，云海出现率高。","addr":"井冈山市黄洋界景区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游吉安一带氛围拉满，晚餐红米饭南瓜汤人均45元。","addr":"茨坪天街","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"茨坪革命旧址群","description":"全天主景点茨坪革命旧址群，旧址集中，步行串游。","addr":"井冈山市茨坪镇","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐井冈烟笋（人均38元），早点休息。","addr":"黄洋界山下餐馆","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"龙潭","description":"收官龙潭，五潭十八瀑，索道省力。","addr":"井冈山龙潭景区","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐石鸡炖汤后集合返程，三日旅程圆满。","addr":"龙潭景区入口","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"黄洋界","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"黄洋界是井冈山最有代表性的看点，保卫战旧址，云海出现率高。攻略把它排进主线，时间留得最足。","notice":"保卫战旧址，云海出现率高。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"井冈山市黄洋界景区"},{"spotId":"S2","name":"茨坪革命旧址群","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"茨坪革命旧址群是井冈山最有代表性的看点，旧址集中，步行串游。攻略把它排进主线，时间留得最足。","notice":"旧址集中，步行串游。周边有休息区与补给点，随时停留。","durationMinutes":150,"addr":"井冈山市茨坪镇"},{"spotId":"S3","name":"龙潭","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"龙潭是井冈山最有代表性的看点，五潭十八瀑，索道省力。攻略把它排进主线，时间留得最足。","notice":"五潭十八瀑，索道省力。这个点位上午光线最好。","durationMinutes":180,"addr":"井冈山龙潭景区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"红米饭南瓜汤（人均45元）","description":"吉安 · 井冈山的招牌是红米饭南瓜汤，老乡家常菜本地人都认这家，点单照攻略不踩雷。","addr":"茨坪天街"},{"title":"井冈烟笋（人均38元）","description":"吉安 · 井冈山的招牌是井冈烟笋，山上饭庄本地人都认这家，点单照攻略不踩雷。","addr":"黄洋界山下餐馆"},{"title":"石鸡炖汤（人均88元）","description":"吉安 · 井冈山的招牌是石鸡炖汤，龙潭农庄本地人都认这家，点单照攻略不踩雷。","addr":"龙潭景区入口"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1795,"required":false},{"name":"住宿参考","amount":1396,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["保温水杯与少量现金","身份证件与手机充电宝","常用药品（肠胃药/创可贴）","换洗衣物与外套（早晚温差）","防晒霜与遮阳帽","轻便雨衣或折叠伞","相机或运动相机","少量零食补给"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["饮食注意卫生，海鲜过敏提前告知店家","山区信号弱，提前下载离线地图","涉水项目穿好救生衣，听从工作人员安排","看好同行老人小孩，走失原地等待"],"faqs":[["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["当地有什么必吃？","到了 吉安，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"]]}',2,'有些风景，照片永远差一点，比如你亲眼看到的那一刻。','on');
INSERT INTO `travel_route` (`id`,`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES (1131,'庐山纯攻略·臻享版5','guide','江西 · 九江','mountain','https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80',3990,1995,2,'锦绣谷 / 三叠泉 / 如琴湖花径 —— 深度攻略助你玩透庐山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「庐山」两日慢旅行——山岳。庐山云雾茶记得认准原产地标志。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 九江"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴九江","description":"集合出发，大巴直达庐山，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"锦绣谷","description":"抵达后首游锦绣谷，云雾多发地段，下午常被云海包裹。","addr":"庐山风景区","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐庐山三石宴（人均128元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"三叠泉","description":"早起人少，三叠泉精华时段，不到三叠泉不算庐山客，往返台阶多。","addr":"庐山东南麓","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐茶饼，人均12元，补充体力。","addr":"牯岭镇正街","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"如琴湖花径","description":"午后游览如琴湖花径，清晨人少出片，环湖半小时。","addr":"牯岭镇西侧","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"锦绣谷","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"锦绣谷是庐山最有代表性的看点，云雾多发地段，下午常被云海包裹。攻略把它排进主线，时间留得最足。","notice":"云雾多发地段，下午常被云海包裹。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"庐山风景区"},{"spotId":"S2","name":"三叠泉","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"三叠泉是庐山最有代表性的看点，不到三叠泉不算庐山客，往返台阶多。攻略把它排进主线，时间留得最足。","notice":"不到三叠泉不算庐山客，往返台阶多。拍照记得留神脚下台阶。","durationMinutes":240,"addr":"庐山东南麓"},{"spotId":"S3","name":"如琴湖花径","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"如琴湖花径是庐山最有代表性的看点，清晨人少出片，环湖半小时。攻略把它排进主线，时间留得最足。","notice":"清晨人少出片，环湖半小时。这个点位上午光线最好。","durationMinutes":60,"addr":"牯岭镇西侧"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"庐山三石宴（人均128元）","description":"九江 · 庐山的招牌是庐山三石宴，牯岭镇饭馆本地人都认这家，点单照攻略不踩雷。","addr":"牯岭镇河西路"},{"title":"茶饼（人均12元）","description":"九江 · 庐山的招牌是茶饼，云中街区小店本地人都认这家，点单照攻略不踩雷。","addr":"牯岭镇正街"},{"title":"石耳炖鸡汤（人均98元）","description":"九江 · 庐山的招牌是石耳炖鸡汤，山中食府本地人都认这家，点单照攻略不踩雷。","addr":"如琴湖旁农家"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1795,"required":false},{"name":"住宿参考","amount":1396,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["舒适徒步鞋（防滑鞋底）","保温水杯与少量现金","常用药品（肠胃药/创可贴）","身份证件与手机充电宝","轻便雨衣或折叠伞","少量零食补给","相机或运动相机","防晒霜与遮阳帽"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["涉水项目穿好救生衣，听从工作人员安排","饮食注意卫生，海鲜过敏提前告知店家","高原地区避免剧烈运动，备好氧气瓶","恶劣天气听从景区安排，不进入未开放区域"],"faqs":[["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["当地有什么必吃？","到了 九江，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"]]}',2,'好运藏在出发的行囊里。','on');
INSERT INTO `travel_route` (`id`,`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES (1132,'龙虎山纯攻略·臻享版6','guide','江西 · 鹰潭','water','https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80',3990,1995,2,'仙水岩 / 泸溪河竹筏 / 上清古镇 —— 深度攻略助你玩透龙虎山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「龙虎山」三日深度游——水景。龙虎山道教养生茶值得带。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 鹰潭"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往鹰潭，抵达后办理入住、熟悉周边环境。","addr":"鹰潭市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"仙水岩","description":"下午首站仙水岩，调整状态进入旅行节奏，悬棺表演一天四场，提前占前排。","addr":"龙虎山仙水岩景区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游鹰潭一带氛围拉满，晚餐天师板栗烧鸡人均68元。","addr":"上清古镇长街","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"泸溪河竹筏","description":"全天主景点泸溪河竹筏，顺流漂90分钟，防晒必做。","addr":"龙虎山竹筏码头","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐泸溪河鱼（人均58元），早点休息。","addr":"竹筏码头旁","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"上清古镇","description":"收官上清古镇，天师府在此，古街人少。","addr":"龙虎山上清镇","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐上清豆腐后集合返程，三日旅程圆满。","addr":"上清古街中段","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"仙水岩","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"仙水岩是龙虎山最有代表性的看点，悬棺表演一天四场，提前占前排。攻略把它排进主线，时间留得最足。","notice":"悬棺表演一天四场，提前占前排。这个点位上午光线最好。","durationMinutes":120,"addr":"龙虎山仙水岩景区"},{"spotId":"S2","name":"泸溪河竹筏","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"泸溪河竹筏是龙虎山最有代表性的看点，顺流漂90分钟，防晒必做。攻略把它排进主线，时间留得最足。","notice":"顺流漂90分钟，防晒必做。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"龙虎山竹筏码头"},{"spotId":"S3","name":"上清古镇","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"上清古镇是龙虎山最有代表性的看点，天师府在此，古街人少。攻略把它排进主线，时间留得最足。","notice":"天师府在此，古街人少。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"龙虎山上清镇"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"天师板栗烧鸡（人均68元）","description":"鹰潭 · 龙虎山的招牌是天师板栗烧鸡，上清古镇饭店本地人都认这家，点单照攻略不踩雷。","addr":"上清古镇长街"},{"title":"泸溪河鱼（人均58元）","description":"鹰潭 · 龙虎山的招牌是泸溪河鱼，仙水岩渔家本地人都认这家，点单照攻略不踩雷。","addr":"竹筏码头旁"},{"title":"上清豆腐（人均20元）","description":"鹰潭 · 龙虎山的招牌是上清豆腐，古镇豆腐坊本地人都认这家，点单照攻略不踩雷。","addr":"上清古街中段"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1795,"required":false},{"name":"住宿参考","amount":1396,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["换洗衣物与外套（早晚温差）","轻便雨衣或折叠伞","舒适徒步鞋（防滑鞋底）","常用药品（肠胃药/创可贴）","保温水杯与少量现金","防晒霜与遮阳帽","墨镜与拍照道具","身份证件与手机充电宝"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["山区信号弱，提前下载离线地图","饮食注意卫生，海鲜过敏提前告知店家","高原地区避免剧烈运动，备好氧气瓶","看好同行老人小孩，走失原地等待"],"faqs":[["几月份去 鹰潭 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["到达 鹰潭 的交通方便吗？","推荐先到 鹰潭，再打车或景区直通车前往核心景区；自驾导航直接搜龙虎山即可。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"]]}',2,'这一次，把心跳交给山野。','on');
INSERT INTO `travel_route` (`id`,`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES (1133,'滕王阁纯攻略·臻享版7','guide','江西 · 南昌','art','https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80',3990,1995,5,'滕王阁 / 万寿宫历史文化街区 / 秋水广场 —— 深度攻略助你玩透滕王阁精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「滕王阁」两日慢旅行——文艺。南昌瓷板画是独特纪念品。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 南昌"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴南昌","description":"集合出发，大巴直达滕王阁，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"滕王阁","description":"抵达后首游滕王阁，落霞与孤鹜齐名的主阁，登顶看赣江。","addr":"南昌市东湖区仿古街58号","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐瓦罐汤（人均18元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"万寿宫历史文化街区","description":"早起人少，万寿宫历史文化街区精华时段，夜市烟火气，白天逛老建筑。","addr":"西湖区中山路","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐拌粉，人均12元，补充体力。","addr":"中山路支巷","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"秋水广场","description":"午后游览秋水广场，亚洲最大音乐喷泉群，晚上两场。","addr":"红谷滩区赣江中大道","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"滕王阁","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"滕王阁是滕王阁最有代表性的看点，落霞与孤鹜齐名的主阁，登顶看赣江。攻略把它排进主线，时间留得最足。","notice":"落霞与孤鹜齐名的主阁，登顶看赣江。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"南昌市东湖区仿古街58号"},{"spotId":"S2","name":"万寿宫历史文化街区","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"万寿宫历史文化街区是滕王阁最有代表性的看点，夜市烟火气，白天逛老建筑。攻略把它排进主线，时间留得最足。","notice":"夜市烟火气，白天逛老建筑。这个点位上午光线最好。","durationMinutes":120,"addr":"西湖区中山路"},{"spotId":"S3","name":"秋水广场","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"秋水广场是滕王阁最有代表性的看点，亚洲最大音乐喷泉群，晚上两场。攻略把它排进主线，时间留得最足。","notice":"亚洲最大音乐喷泉群，晚上两场。周边有休息区与补给点，随时停留。","durationMinutes":60,"addr":"红谷滩区赣江中大道"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"瓦罐汤（人均18元）","description":"南昌 · 滕王阁的招牌是瓦罐汤，民间瓦罐汤店本地人都认这家，点单照攻略不踩雷。","addr":"万寿宫街区巷口"},{"title":"拌粉（人均12元）","description":"南昌 · 滕王阁的招牌是拌粉，南昌拌粉总店本地人都认这家，点单照攻略不踩雷。","addr":"中山路支巷"},{"title":"白糖糕（人均8元）","description":"南昌 · 滕王阁的招牌是白糖糕，老字号糕点铺本地人都认这家，点单照攻略不踩雷。","addr":"万寿宫内街"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1795,"required":false},{"name":"住宿参考","amount":1396,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["保温水杯与少量现金","换洗衣物与外套（早晚温差）","少量零食补给","常用药品（肠胃药/创可贴）","轻便雨衣或折叠伞","防晒霜与遮阳帽","相机或运动相机","身份证件与手机充电宝"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["高原地区避免剧烈运动，备好氧气瓶","涉水项目穿好救生衣，听从工作人员安排","看好同行老人小孩，走失原地等待","恶劣天气听从景区安排，不进入未开放区域"],"faqs":[["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["当地有什么必吃？","到了 南昌，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["几月份去 南昌 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"]]}',2,'远方的炊烟，是写给旅人的信。','on');
INSERT INTO `travel_route` (`id`,`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES (1134,'陶溪川纯攻略·臻享版8','guide','江西 · 景德镇','art','https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80',3990,1995,5,'陶溪川文创街区 / 古窑民俗博览区 / 雕塑瓷厂乐天市集 —— 深度攻略助你玩透陶溪川精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「陶溪川」三日深度游——文艺。景德镇薄胎瓷碗轻巧又体面。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 景德镇"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往景德镇，抵达后办理入住、熟悉周边环境。","addr":"景德镇市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"陶溪川文创街区","description":"下午首站陶溪川文创街区，调整状态进入旅行节奏，夜市周五六日开，手作摊最好逛。","addr":"珠山区新厂西路","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游景德镇一带氛围拉满，晚餐饺子粑人均15元。","addr":"中山北路","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"古窑民俗博览区","description":"全天主景点古窑民俗博览区，看柴窑镇窑复烧，拉坯体验要排队。","addr":"昌江区枫树山蟠龙岗","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐冷粉（人均12元），早点休息。","addr":"人民广场附近","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"雕塑瓷厂乐天市集","description":"收官雕塑瓷厂乐天市集，周六上午开市，淘手作好物。","addr":"新厂东路139号","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐碱水粑炒鸡蛋后集合返程，三日旅程圆满。","addr":"陶溪川周边小馆","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"陶溪川文创街区","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"陶溪川文创街区是陶溪川最有代表性的看点，夜市周五六日开，手作摊最好逛。攻略把它排进主线，时间留得最足。","notice":"夜市周五六日开，手作摊最好逛。拍照记得留神脚下台阶。","durationMinutes":150,"addr":"珠山区新厂西路"},{"spotId":"S2","name":"古窑民俗博览区","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"古窑民俗博览区是陶溪川最有代表性的看点，看柴窑镇窑复烧，拉坯体验要排队。攻略把它排进主线，时间留得最足。","notice":"看柴窑镇窑复烧，拉坯体验要排队。提前10分钟到，避开旅行团大部队。","durationMinutes":150,"addr":"昌江区枫树山蟠龙岗"},{"spotId":"S3","name":"雕塑瓷厂乐天市集","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"雕塑瓷厂乐天市集是陶溪川最有代表性的看点，周六上午开市，淘手作好物。攻略把它排进主线，时间留得最足。","notice":"周六上午开市，淘手作好物。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"新厂东路139号"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"饺子粑（人均15元）","description":"景德镇 · 陶溪川的招牌是饺子粑，老字号小吃店本地人都认这家，点单照攻略不踩雷。","addr":"中山北路"},{"title":"冷粉（人均12元）","description":"景德镇 · 陶溪川的招牌是冷粉，景德镇冷粉店本地人都认这家，点单照攻略不踩雷。","addr":"人民广场附近"},{"title":"碱水粑炒鸡蛋（人均28元）","description":"景德镇 · 陶溪川的招牌是碱水粑炒鸡蛋，瓷都家常菜本地人都认这家，点单照攻略不踩雷。","addr":"陶溪川周边小馆"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1795,"required":false},{"name":"住宿参考","amount":1396,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["身份证件与手机充电宝","防晒霜与遮阳帽","常用药品（肠胃药/创可贴）","墨镜与拍照道具","换洗衣物与外套（早晚温差）","舒适徒步鞋（防滑鞋底）","保温水杯与少量现金","少量零食补给"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["贵重物品随身携带，景区人多注意","夜间出行结伴，走主路不抄小道","高原地区避免剧烈运动，备好氧气瓶","山区信号弱，提前下载离线地图"],"faqs":[["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"]]}',2,'慢一点，风景才来得及认识你。','on');
INSERT INTO `travel_route` (`id`,`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES (1135,'明月山纯攻略·臻享版9','guide','江西 · 宜春','mountain','https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80',3990,1995,2,'青云栈道 / 云谷飞瀑 / 温汤镇古井泉街 —— 深度攻略助你玩透明月山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「明月山」两日慢旅行——山岳。温汤富硒温泉蛋一元一个。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 宜春"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴宜春","description":"集合出发，大巴直达明月山，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"青云栈道","description":"抵达后首游青云栈道，悬空栈道绕山腰，云雾天如仙境。","addr":"明月山风景区","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐温泉豆腐（人均48元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"云谷飞瀑","description":"早起人少，云谷飞瀑精华时段，宜春八景之一，负氧离子爆表。","addr":"明月山核心景区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐慈化鸡爪，人均22元，补充体力。","addr":"温汤镇主街","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"温汤镇古井泉街","description":"午后游览温汤镇古井泉街，富硒温泉足浴28元一位，晚上泡最解乏。","addr":"袁州区温汤镇","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"青云栈道","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"青云栈道是明月山最有代表性的看点，悬空栈道绕山腰，云雾天如仙境。攻略把它排进主线，时间留得最足。","notice":"悬空栈道绕山腰，云雾天如仙境。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"明月山风景区"},{"spotId":"S2","name":"云谷飞瀑","coverUrl":"https://images.unsplas