INSERT INTO `travel_route` (`id`,`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES (1136,'仙女湖纯攻略·臻享版10','guide','江西 · 新余','water','https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80',3990,1995,2,'仙女湖主体湖区 / 圣集寺 / 龙王阁 —— 深度攻略助你玩透仙女湖精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「仙女湖」三日深度游——水景。新余蜜桔十月后最甜。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 新余"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往新余，抵达后办理入住、熟悉周边环境。","addr":"新余市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"仙女湖主体湖区","description":"下午首站仙女湖主体湖区，调整状态进入旅行节奏，坐船跳岛游，爱情岛最热门。","addr":"新余市渝水区仙女湖大道","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游新余一带氛围拉满，晚餐仙女湖鱼头人均78元。","addr":"仙女湖码头渔家街","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"圣集寺","description":"全天主景点圣集寺，湖畔禅意，人少清净。","addr":"仙女湖钤阳湖畔","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐新余蜜桔鸡（人均58元），早点休息。","addr":"景区出口农家乐","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"龙王阁","description":"收官龙王阁，登阁看千岛湖景。","addr":"仙女湖最高点","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐水北豆腐后集合返程，三日旅程圆满。","addr":"新余城区","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"仙女湖主体湖区","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"仙女湖主体湖区是仙女湖最有代表性的看点，坐船跳岛游，爱情岛最热门。攻略把它排进主线，时间留得最足。","notice":"坐船跳岛游，爱情岛最热门。这个点位上午光线最好。","durationMinutes":180,"addr":"新余市渝水区仙女湖大道"},{"spotId":"S2","name":"圣集寺","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"圣集寺是仙女湖最有代表性的看点，湖畔禅意，人少清净。攻略把它排进主线，时间留得最足。","notice":"湖畔禅意，人少清净。提前10分钟到，避开旅行团大部队。","durationMinutes":60,"addr":"仙女湖钤阳湖畔"},{"spotId":"S3","name":"龙王阁","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"龙王阁是仙女湖最有代表性的看点，登阁看千岛湖景。攻略把它排进主线，时间留得最足。","notice":"登阁看千岛湖景。周边有休息区与补给点，随时停留。","durationMinutes":60,"addr":"仙女湖最高点"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"仙女湖鱼头（人均78元）","description":"新余 · 仙女湖的招牌是仙女湖鱼头，湖畔渔村本地人都认这家，点单照攻略不踩雷。","addr":"仙女湖码头渔家街"},{"title":"新余蜜桔鸡（人均58元）","description":"新余 · 仙女湖的招牌是新余蜜桔鸡，农家菜馆本地人都认这家，点单照攻略不踩雷。","addr":"景区出口农家乐"},{"title":"水北豆腐（人均25元）","description":"新余 · 仙女湖的招牌是水北豆腐，老豆腐坊本地人都认这家，点单照攻略不踩雷。","addr":"新余城区"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1795,"required":false},{"name":"住宿参考","amount":1396,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["舒适徒步鞋（防滑鞋底）","轻便雨衣或折叠伞","身份证件与手机充电宝","防晒霜与遮阳帽","换洗衣物与外套（早晚温差）","常用药品（肠胃药/创可贴）","少量零食补给","相机或运动相机"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["看好同行老人小孩，走失原地等待","高原地区避免剧烈运动，备好氧气瓶","涉水项目穿好救生衣，听从工作人员安排","贵重物品随身携带，景区人多注意"],"faqs":[["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"]]}',2,'山高水长，都是给你准备的惊喜。','on');
INSERT INTO `travel_route` (`id`,`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES (1137,'大觉山纯攻略·臻享版11','guide','江西 · 抚州','adventure','https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80',3990,1995,9,'大觉山漂流 / 大觉岩寺 / 古镇影视城 —— 深度攻略助你玩透大觉山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「大觉山」两日慢旅行——探险地。资溪面包是当地人的骄傲。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 抚州"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴抚州","description":"集合出发，大巴直达大觉山，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"大觉山漂流","description":"抵达后首游大觉山漂流，华东第一漂，全程3.5公里带好换洗衣。","addr":"资溪县大觉山景区","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐资溪面包（人均15元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"大觉岩寺","description":"早起人少，大觉岩寺精华时段，悬崖上的古寺，索道直达。","addr":"大觉山主峰","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐笋干烧肉，人均48元，补充体力。","addr":"大觉山游客中心","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"古镇影视城","description":"午后游览古镇影视城，仿宋古镇，拍照出片。","addr":"大觉山脚下","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"大觉山漂流","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"大觉山漂流是大觉山最有代表性的看点，华东第一漂，全程3.5公里带好换洗衣。攻略把它排进主线，时间留得最足。","notice":"华东第一漂，全程3.5公里带好换洗衣。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"资溪县大觉山景区"},{"spotId":"S2","name":"大觉岩寺","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"大觉岩寺是大觉山最有代表性的看点，悬崖上的古寺，索道直达。攻略把它排进主线，时间留得最足。","notice":"悬崖上的古寺，索道直达。这个点位上午光线最好。","durationMinutes":120,"addr":"大觉山主峰"},{"spotId":"S3","name":"古镇影视城","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"古镇影视城是大觉山最有代表性的看点，仿宋古镇，拍照出片。攻略把它排进主线，时间留得最足。","notice":"仿宋古镇，拍照出片。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"大觉山脚下"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"资溪面包（人均15元）","description":"抚州 · 大觉山的招牌是资溪面包，面包之乡旗舰店本地人都认这家，点单照攻略不踩雷。","addr":"资溪县城"},{"title":"笋干烧肉（人均48元）","description":"抚州 · 大觉山的招牌是笋干烧肉，山脚农家本地人都认这家，点单照攻略不踩雷。","addr":"大觉山游客中心"},{"title":"发酵豆腐（人均18元）","description":"抚州 · 大觉山的招牌是发酵豆腐，古镇豆坊本地人都认这家，点单照攻略不踩雷。","addr":"影视城内街"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1795,"required":false},{"name":"住宿参考","amount":1396,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["舒适徒步鞋（防滑鞋底）","身份证件与手机充电宝","墨镜与拍照道具","保温水杯与少量现金","少量零食补给","常用药品（肠胃药/创可贴）","相机或运动相机","轻便雨衣或折叠伞"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["高原地区避免剧烈运动，备好氧气瓶","贵重物品随身携带，景区人多注意","涉水项目穿好救生衣，听从工作人员安排","恶劣天气听从景区安排，不进入未开放区域"],"faqs":[["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"]]}',2,'这一程，山水都在替你说话。','on');
