INSERT INTO `travel_route` (`id`,`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES (1145,'桃花源纯攻略·臻享版19','guide','湖南 · 常德','village','https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80',3990,1995,1,'桃花源古镇 / 桃源山 / 五柳湖 —— 深度攻略助你玩透桃花源精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「桃花源」两日慢旅行——古村落。桃源大叶茶配擂茶绝了。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖南 · 常德"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴常德","description":"集合出发，大巴直达桃花源，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"桃花源古镇","description":"抵达后首游桃花源古镇，秦溪秦谷还原桃花源记场景。","addr":"常德市桃源县","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐常德米粉（人均18元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"桃源山","description":"早起人少，桃源山精华时段，水府阁俯瞰沅江。","addr":"桃花源景区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐擂茶，人均35元，补充体力。","addr":"桃花源古镇内","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"五柳湖","description":"午后游览五柳湖，落英缤纷打卡点。","addr":"桃花源核心区","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"桃花源古镇","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"桃花源古镇是桃花源最有代表性的看点，秦溪秦谷还原桃花源记场景。攻略把它排进主线，时间留得最足。","notice":"秦溪秦谷还原桃花源记场景。这个点位上午光线最好。","durationMinutes":150,"addr":"常德市桃源县"},{"spotId":"S2","name":"桃源山","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"桃源山是桃花源最有代表性的看点，水府阁俯瞰沅江。攻略把它排进主线，时间留得最足。","notice":"水府阁俯瞰沅江。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"桃花源景区"},{"spotId":"S3","name":"五柳湖","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"五柳湖是桃花源最有代表性的看点，落英缤纷打卡点。攻略把它排进主线，时间留得最足。","notice":"落英缤纷打卡点。提前10分钟到，避开旅行团大部队。","durationMinutes":60,"addr":"桃花源核心区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"常德米粉（人均18元）","description":"常德 · 桃花源的招牌是常德米粉，刘聋子粉馆本地人都认这家，点单照攻略不踩雷。","addr":"桃源县漳江镇"},{"title":"擂茶（人均35元）","description":"常德 · 桃花源的招牌是擂茶，秦溪擂茶馆本地人都认这家，点单照攻略不踩雷。","addr":"桃花源古镇内"},{"title":"桃源鸡（人均68元）","description":"常德 · 桃花源的招牌是桃源鸡，农家菜馆本地人都认这家，点单照攻略不踩雷。","addr":"景区出口"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1795,"required":false},{"name":"住宿参考","amount":1396,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["墨镜与拍照道具","换洗衣物与外套（早晚温差）","身份证件与手机充电宝","轻便雨衣或折叠伞","常用药品（肠胃药/创可贴）","相机或运动相机","保温水杯与少量现金","少量零食补给"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["涉水项目穿好救生衣，听从工作人员安排","恶劣天气听从景区安排，不进入未开放区域","夜间出行结伴，走主路不抄小道","山区信号弱，提前下载离线地图"],"faqs":[["到达 常德 的交通方便吗？","推荐先到 常德，再打车或景区直通车前往核心景区；自驾导航直接搜桃花源即可。"],["几月份去 常德 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"]]}',2,'今天的夕阳，为你的抵达打光。','on');
INSERT INTO `travel_route` (`id`,`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES (1146,'紫鹊界梯田纯攻略·臻享版20','guide','湖南 · 娄底','village','https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80',3990,1995,1,'紫鹊界梯田 / 正龙古村 / 梅山龙宫 —— 深度攻略助你玩透紫鹊界梯田精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「紫鹊界梯田」三日深度游——古村落。新化黄精茶养生。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖南 · 娄底"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往娄底，抵达后办理入住、熟悉周边环境。","addr":"娄底市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"紫鹊界梯田","description":"下午首站紫鹊界梯田，调整状态进入旅行节奏，两千年秦人梯田，月牙山八仙过海。","addr":"娄底市新化县","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游娄底一带氛围拉满，晚餐新化三合汤人均38元。","addr":"新化县城","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"正龙古村","description":"全天主景点正龙古村，干栏式板屋村落。","addr":"紫鹊界脚下","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐杯子糕（人均10元），早点休息。","addr":"紫鹊界","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"梅山龙宫","description":"收官梅山龙宫，地下溶洞暗河乘船。","addr":"新化县","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐柴火腊肉后集合返程，三日旅程圆满。","addr":"正龙古村","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"紫鹊界梯田","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"紫鹊界梯田是紫鹊界梯田最有代表性的看点，两千年秦人梯田，月牙山八仙过海。攻略把它排进主线，时间留得最足。","notice":"两千年秦人梯田，月牙山八仙过海。这个点位上午光线最好。","durationMinutes":180,"addr":"娄底市新化县"},{"spotId":"S2","name":"正龙古村","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"正龙古村是紫鹊界梯田最有代表性的看点，干栏式板屋村落。攻略把它排进主线，时间留得最足。","notice":"干栏式板屋村落。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"紫鹊界脚下"},{"spotId":"S3","name":"梅山龙宫","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"梅山龙宫是紫鹊界梯田最有代表性的看点，地下溶洞暗河乘船。攻略把它排进主线，时间留得最足。","notice":"地下溶洞暗河乘船。这个点位上午光线最好。","durationMinutes":150,"addr":"新化县"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"新化三合汤（人均38元）","description":"娄底 · 紫鹊界梯田的招牌是新化三合汤，老字号三合汤本地人都认这家，点单照攻略不踩雷。","addr":"新化县城"},{"title":"杯子糕（人均10元）","description":"娄底 · 紫鹊界梯田的招牌是杯子糕，街头小吃本地人都认这家，点单照攻略不踩雷。","addr":"紫鹊界"},{"title":"柴火腊肉（人均45元）","description":"娄底 · 紫鹊界梯田的招牌是柴火腊肉，农家直购本地人都认这家，点单照攻略不踩雷。","addr":"正龙古村"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1795,"required":false},{"name":"住宿参考","amount":1396,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["保温水杯与少量现金","相机或运动相机","防晒霜与遮阳帽","舒适徒步鞋（防滑鞋底）","身份证件与手机充电宝","墨镜与拍照道具","换洗衣物与外套（早晚温差）","少量零食补给"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["看好同行老人小孩，走失原地等待","贵重物品随身携带，景区人多注意","夜间出行结伴，走主路不抄小道","涉水项目穿好救生衣，听从工作人员安排"],"faqs":[["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["到达 娄底 的交通方便吗？","推荐先到 娄底，再打车或景区直通车前往核心景区；自驾导航直接搜紫鹊界梯田即可。"],["几月份去 娄底 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"]]}',2,'山高水长，都是给你准备的惊喜。','on');
INSERT INTO `travel_route` (`id`,`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES (1147,'大理古城洱海纯攻略·臻享版21','guide','云南 · 大理','water','https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80',4990,2495,2,'洱海生态廊道 / 大理古城 / 崇圣寺三塔 —— 深度攻略助你玩透大理古城洱海精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「大理古城洱海」两日慢旅行——水景。喜洲粑粑现烤的最香。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"云南 · 大理"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴大理","description":"集合出发，大巴直达大理古城洱海，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"洱海生态廊道","description":"抵达后首游洱海生态廊道，租电动车骑行，S湾拍倒影。","addr":"大理市环海西路","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐白族三道茶（人均48元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"大理古城","description":"早起人少，大理古城精华时段，洋人街与五华楼，夜晚酒吧街热闹。","addr":"大理市一塔路","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐砂锅鱼，人均78元，补充体力。","addr":"才村码头","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"崇圣寺三塔","description":"午后游览崇圣寺三塔，大理地标，倒影公园拍三塔。","addr":"大理市三塔路","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"洱海生态廊道","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"洱海生态廊道是大理古城洱海最有代表性的看点，租电动车骑行，S湾拍倒影。攻略把它排进主线，时间留得最足。","notice":"租电动车骑行，S湾拍倒影。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"大理市环海西路"},{"spotId":"S2","name":"大理古城","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"大理古城是大理古城洱海最有代表性的看点，洋人街与五华楼，夜晚酒吧街热闹。攻略把它排进主线，时间留得最足。","notice":"洋人街与五华楼，夜晚酒吧街热闹。拍照记得留神脚下台阶。","durationMinutes":150,"addr":"大理市一塔路"},{"spotId":"S3","name":"崇圣寺三塔","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"崇圣寺三塔是大理古城洱海最有代表性的看点，大理地标，倒影公园拍三塔。攻略把它排进主线，时间留得最足。","notice":"大理地标，倒影公园拍三塔。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"大理市三塔路"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"白族三道茶（人均48元）","description":"大理 · 大理古城洱海的招牌是白族三道茶，严家大院本地人都认这家，点单照攻略不踩雷。","addr":"喜洲古镇"},{"title":"砂锅鱼（人均78元）","description":"大理 · 大理古城洱海的招牌是砂锅鱼，大理砂锅鱼庄本地人都认这家，点单照攻略不踩雷。","addr":"才村码头"},{"title":"乳扇（人均12元）","description":"大理 · 大理古城洱海的招牌是乳扇，杨记乳扇本地人都认这家，点单照攻略不踩雷。","addr":"古城人民路"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":2245,"required":false},{"name":"住宿参考","amount":1746,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["身份证件与手机充电宝","常用药品（肠胃药/创可贴）","保温水杯与少量现金","轻便雨衣或折叠伞","相机或运动相机","墨镜与拍照道具","换洗衣物与外套（早晚温差）","少量零食补给"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["饮食注意卫生，海鲜过敏提前告知店家","山区信号弱，提前下载离线地图","高原地区避免剧烈运动，备好氧气瓶","涉水项目穿好救生衣，听从工作人员安排"],"faqs":[["当地有什么必吃？","到了 大理，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["几月份去 大理 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"]]}',2,'这一程，山水都在替你说话。','on');
INSERT INTO `travel_route` (`id`,`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES (1148,'丽江古城玉龙雪山纯攻略·臻享版22','guide','云南 · 丽江','mountain','https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80',4990,2495,2,'玉龙雪山 / 蓝月谷 / 丽江古城 —— 深度攻略助你玩透丽江古城玉龙雪山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「丽江古城玉龙雪山」三日深度游——山岳。雪山玫瑰饼是最热手信。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"云南 · 丽江"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往丽江，抵达后办理入住、熟悉周边环境。","addr":"丽江市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"玉龙雪山","description":"下午首站玉龙雪山，调整状态进入旅行节奏，大索道直达4506米，租羽绒服买氧气瓶。","addr":"丽江市玉龙县","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游丽江一带氛围拉满，晚餐腊排骨火锅人均68元。","addr":"古城区象山街","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"蓝月谷","description":"全天主景点蓝月谷，牛奶蓝湖水，电瓶车游三湖。","addr":"玉龙雪山脚下","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐鸡豆凉粉（人均10元），早点休息。","addr":"四方街","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"丽江古城","description":"收官丽江古城，四方街打跳，狮子山看全景。","addr":"古城区","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐丽江粑粑后集合返程，三日旅程圆满。","addr":"忠义市场内","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"玉龙雪山","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"玉龙雪山是丽江古城玉龙雪山最有代表性的看点，大索道直达4506米，租羽绒服买氧气瓶。攻略把它排进主线，时间留得最足。","notice":"大索道直达4506米，租羽绒服买氧气瓶。周边有休息区与补给点，随时停留。","durationMinutes":300,"addr":"丽江市玉龙县"},{"spotId":"S2","name":"蓝月谷","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"蓝月谷是丽江古城玉龙雪山最有代表性的看点，牛奶蓝湖水，电瓶车游三湖。攻略把它排进主线，时间留得最足。","notice":"牛奶蓝湖水，电瓶车游三湖。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"玉龙雪山脚下"},{"spotId":"S3","name":"丽江古城","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"丽江古城是丽江古城玉龙雪山最有代表性的看点，四方街打跳，狮子山看全景。攻略把它排进主线，时间留得最足。","notice":"四方街打跳，狮子山看全景。这个点位上午光线最好。","durationMinutes":180,"addr":"古城区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"腊排骨火锅（人均68元）","description":"丽江 · 丽江古城玉龙雪山的招牌是腊排骨火锅，象山市场本地人都认这家，点单照攻略不踩雷。","addr":"古城区象山街"},{"title":"鸡豆凉粉（人均10元）","description":"丽江 · 丽江古城玉龙雪山的招牌是鸡豆凉粉，古城小吃摊本地人都认这家，点单照攻略不踩雷。","addr":"四方街"},{"title":"丽江粑粑（人均12元）","description":"丽江 · 丽江古城玉龙雪山的招牌是丽江粑粑，忠义市场本地人都认这家，点单照攻略不踩雷。","addr":"忠义市场内"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":2245,"required":false},{"name":"住宿参考","amount":1746,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["身份证件与手机充电宝","少量零食补给","常用药品（肠胃药/创可贴）","保温水杯与少量现金","舒适徒步鞋（防滑鞋底）","轻便雨衣或折叠伞","墨镜与拍照道具","换洗衣物与外套（早晚温差）"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["饮食注意卫生，海鲜过敏提前告知店家","山区信号弱，提前下载离线地图","贵重物品随身携带，景区人多注意","恶劣天气听从景区安排，不进入未开放区域"],"faqs":[["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["几月份去 丽江 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"]]}',2,'出发这一刻，惊喜已经在路上。','on');
INSERT INTO `travel_route` (`id`,`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES (1149,'香格里拉纯攻略·臻享版23','guide','云南 · 迪庆','plateau','https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80',4990,2495,2,'普达措国家公园 / 松赞林寺 / 独克宗古城 —— 深度攻略助你玩透香格里拉精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「香格里拉」两日慢旅行——高原。牦牛肉干认准风干原味。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"云南 · 迪庆"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴迪庆","description":"集合出发，大巴直达香格里拉，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"普达措国家公园","description":"抵达后首游普达措国家公园，属都湖栈道环湖，高原慢慢走。","addr":"香格里拉市建塘镇","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐牦牛肉火锅（人均88元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"松赞林寺","description":"早起人少，松赞林寺精华时段，小布达拉宫，顺时针转寺。","addr":"香格里拉市佛屏山前","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐酥油茶，人均20元，补充体力。","addr":"古城内","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"独克宗古城","description":"午后游览独克宗古城，转世界最大转经筒，夜景美。","addr":"香格里拉市","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"普达措国家公园","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"普达措国家公园是香格里拉最有代表性的看点，属都湖栈道环湖，高原慢慢走。攻略把它排进主线，时间留得最足。","notice":"属都湖栈道环湖，高原慢慢走。拍照记得留神脚下台阶。","durationMinutes":240,"addr":"香格里拉市建塘镇"},{"spotId":"S2","name":"松赞林寺","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"松赞林寺是香格里拉最有代表性的看点，小布达拉宫，顺时针转寺。攻略把它排进主线，时间留得最足。","notice":"小布达拉宫，顺时针转寺。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"香格里拉市佛屏山前"},{"spotId":"S3","name":"独克宗古城","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"独克宗古城是香格里拉最有代表性的看点，转世界最大转经筒，夜景美。攻略把它排进主线，时间留得最足。","notice":"转世界最大转经筒，夜景美。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"香格里拉市"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"牦牛肉火锅（人均88元）","description":"迪庆 · 香格里拉的招牌是牦牛肉火锅，市井牦牛火锅本地人都认这家，点单照攻略不踩雷。","addr":"独克宗古城"},{"title":"酥油茶（人均20元）","description":"迪庆 · 香格里拉的招牌是酥油茶，藏家茶馆本地人都认这家，点单照攻略不踩雷。","addr":"古城内"},{"title":"青稞饼（人均12元）","description":"迪庆 · 香格里拉的招牌是青稞饼，藏式饼铺本地人都认这家，点单照攻略不踩雷。","addr":"池慈卡街"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":2245,"required":false},{"name":"住宿参考","amount":1746,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["少量零食补给","保温水杯与少量现金","墨镜与拍照道具","相机或运动相机","换洗衣物与外套（早晚温差）","身份证件与手机充电宝","舒适徒步鞋（防滑鞋底）","轻便雨衣或折叠伞"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["涉水项目穿好救生衣，听从工作人员安排","山区信号弱，提前下载离线地图","贵重物品随身携带，景区人多注意","恶劣天气听从景区安排，不进入未开放区域"],"faqs":[["几月份去 迪庆 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["当地有什么必吃？","到了 迪庆，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"]]}',2,'把日常调成静音，听风与远方的声音。','on');
INSERT INTO `travel_route` (`id`,`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES (1150,'告庄西双景纯攻略·臻享版24','guide','云南 · 西双版纳','sea','https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80',4990,2495,6,'告庄星光夜市 / 曼听公园 / 中科院热带植物园 —— 深度攻略助你玩透告庄西双景精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「告庄西双景」三日深度游——海滨。版纳小粒咖啡香浓不酸。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"云南 · 西双版纳"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往西双版纳，抵达后办理入住、熟悉周边环境。","addr":"西双版纳市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"告庄星光夜市","description":"下午首站告庄星光夜市，调整状态进入旅行节奏，大金塔下的东南亚最大夜市。","addr":"景洪市告庄西双景","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游西双版纳一带氛围拉满，晚餐菠萝饭人均25元。","addr":"星光夜市","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"曼听公园","description":"全天主景点曼听公园，总佛寺相邻，晚场篝火晚会。","addr":"景洪市曼听路","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐香茅草烤鱼（人均48元），早点休息。","addr":"告庄内","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"中科院热带植物园","description":"收官中科院热带植物园，王莲上坐一坐，热气球拍照。","addr":"勐腊县勐仑镇","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐泡鲁达后集合返程，三日旅程圆满。","addr":"大金塔旁","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"告庄星光夜市","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"告庄星光夜市是告庄西双景最有代表性的看点，大金塔下的东南亚最大夜市。攻略把它排进主线，时间留得最足。","notice":"大金塔下的东南亚最大夜市。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"景洪市告庄西双景"},{"spotId":"S2","name":"曼听公园","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"曼听公园是告庄西双景最有代表性的看点，总佛寺相邻，晚场篝火晚会。攻略把它排进主线，时间留得最足。","notice":"总佛寺相邻，晚场篝火晚会。拍照记得留神脚下台阶。","durationMinutes":150,"addr":"景洪市曼听路"},{"spotId":"S3","name":"中科院热带植物园","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"中科院热带植物园是告庄西双景最有代表性的看点，王莲上坐一坐，热气球拍照。攻略把它排进主线，时间留得最足。","notice":"王莲上坐一坐，热气球拍照。提前10分钟到，避开旅行团大部队。","durationMinutes":240,"addr":"勐腊县勐仑镇"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"菠萝饭（人均25元）","description":"西双版纳 · 告庄西双景的招牌是菠萝饭，夜市傣味摊本地人都认这家，点单照攻略不踩雷。","addr":"星光夜市"},{"title":"香茅草烤鱼（人均48元）","description":"西双版纳 · 告庄西双景的招牌是香茅草烤鱼，曼飞龙烤鸡本地人都认这家，点单照攻略不踩雷。","addr":"告庄内"},{"title":"泡鲁达（人均15元）","description":"西双版纳 · 告庄西双景的招牌是泡鲁达，傣家甜品店本地人都认这家，点单照攻略不踩雷。","addr":"大金塔旁"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":2245,"required":false},{"name":"住宿参考","amount":1746,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["少量零食补给","换洗衣物与外套（早晚温差）","舒适徒步鞋（防滑鞋底）","保温水杯与少量现金","常用药品（肠胃药/创可贴）","墨镜与拍照道具","轻便雨衣或折叠伞","身份证件与手机充电宝"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["高原地区避免剧烈运动，备好氧气瓶","山区信号弱，提前下载离线地图","夜间出行结伴，走主路不抄小道","看好同行老人小孩，走失原地等待"],"faqs":[["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["当地有什么必吃？","到了 西双版纳，跟着本攻略的美食清单走就行，本地人都在吃这几家。"]]}',2,'有些风景，照片永远差一点，比如你亲眼看到的那一刻。','on');
INSERT INTO `travel_route` (`id`,`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES (1151,'元阳哈尼梯田纯攻略·臻享版25','guide','云南 · 红河','village','https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80',4990,2495,1,'多依树梯田 / 老虎嘴梯田 / 箐口哈尼民俗村 —— 深度攻略助你玩透元阳哈尼梯田精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「元阳哈尼梯田」两日慢旅行——古村落。元阳红米营养丰富。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"云南 · 红河"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴红河","description":"集合出发，大巴直达元阳哈尼梯田，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"多依树梯田","description":"抵达后首游多依树梯田，日出云海最佳观赏点，提前1小时占位。","addr":"元阳县新街镇","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐哈尼梯田红米（人均35元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"老虎嘴梯田","description":"早起人少，老虎嘴梯田精华时段，日落时梯田变金色。","addr":"元阳县攀枝花乡","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐梯田鱼，人均58元，补充体力。","addr":"箐口村","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"箐口哈尼民俗村","description":"午后游览箐口哈尼民俗村，蘑菇房与梯田同框。","addr":"元阳县","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"多依树梯田","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"多依树梯田是元阳哈尼梯田最有代表性的看点，日出云海最佳观赏点，提前1小时占位。攻略把它排进主线，时间留得最足。","notice":"日出云海最佳观赏点，提前1小时占位。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"元阳县新街镇"},{"spotId":"S2","name":"老虎嘴梯田","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"老虎嘴梯田是元阳哈尼梯田最有代表性的看点，日落时梯田变金色。攻略把它排进主线，时间留得最足。","notice":"日落时梯田变金色。这个点位上午光线最好。","durationMinutes":120,"addr":"元阳县攀枝花乡"},{"spotId":"S3","name":"箐口哈尼民俗村","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"箐口哈尼民俗村是元阳哈尼梯田最有代表性的看点，蘑菇房与梯田同框。攻略把它排进主线，时间留得最足。","notice":"蘑菇房与梯田同框。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"元阳县"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"哈尼梯田红米（人均35元）","description":"红河 · 元阳哈尼梯田的招牌是哈尼梯田红米，农家餐厅本地人都认这家，点单照攻略不踩雷。","addr":"多依树村"},{"title":"梯田鱼（人均58元）","description":"红河 · 元阳哈尼梯田的招牌是梯田鱼，村中渔家本地人都认这家，点单照攻略不踩雷。","addr":"箐口村"},{"title":"竹筒鸡（人均68元）","description":"红河 · 元阳哈尼梯田的招牌是竹筒鸡，哈尼农家本地人都认这家，点单照攻略不踩雷。","addr":"新街镇"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":2245,"required":false},{"name":"住宿参考","amount":1746,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["墨镜与拍照道具","舒适徒步鞋（防滑鞋底）","相机或运动相机","保温水杯与少量现金","轻便雨衣或折叠伞","少量零食补给","换洗衣物与外套（早晚温差）","常用药品（肠胃药/创可贴）"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["涉水项目穿好救生衣，听从工作人员安排","恶劣天气听从景区安排，不进入未开放区域","贵重物品随身携带，景区人多注意","夜间出行结伴，走主路不抄小道"],"faqs":[["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"]]}',2,'好运藏在出发的行囊里。','on');
INSERT INTO `travel_route` (`id`,`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES (1152,'普者黑纯攻略·臻享版26','guide','云南 · 文山','water','https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80',4990,2495,2,'青龙山 / 天鹅湖 / 仙人洞村 —— 深度攻略助你玩透普者黑精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「普者黑」三日深度游——水景。丘北辣椒香而不辣。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"云南 · 文山"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往文山，抵达后办理入住、熟悉周边环境。","addr":"文山市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"青龙山","description":"下午首站青龙山，调整状态进入旅行节奏，登顶看万亩荷塘全景。","addr":"丘北县普者黑村","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游文山一带氛围拉满，晚餐醉虾人均48元。","addr":"普者黑村","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"天鹅湖","description":"全天主景点天鹅湖，候鸟与荷塘，乘船打水仗。","addr":"普者黑景区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐荷叶宴（人均68元），早点休息。","addr":"天鹅湖边","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"仙人洞村","description":"收官仙人洞村，撒尼人村落，民宿夜色美。","addr":"普者黑湖畔","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐丘北辣椒鸡后集合返程，三日旅程圆满。","addr":"丘北县城","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"青龙山","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"青龙山是普者黑最有代表性的看点，登顶看万亩荷塘全景。攻略把它排进主线，时间留得最足。","notice":"登顶看万亩荷塘全景。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"丘北县普者黑村"},{"spotId":"S2","name":"天鹅湖","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"天鹅湖是普者黑最有代表性的看点，候鸟与荷塘，乘船打水仗。攻略把它排进主线，时间留得最足。","notice":"候鸟与荷塘，乘船打水仗。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"普者黑景区"},{"spotId":"S3","name":"仙人洞村","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"仙人洞村是普者黑最有代表性的看点，撒尼人村落，民宿夜色美。攻略把它排进主线，时间留得最足。","notice":"撒尼人村落，民宿夜色美。这个点位上午光线最好。","durationMinutes":120,"addr":"普者黑湖畔"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"醉虾（人均48元）","description":"文山 · 普者黑的招牌是醉虾，湖畔渔家本地人都认这家，点单照攻略不踩雷。","addr":"普者黑村"},{"title":"荷叶宴（人均68元）","description":"文山 · 普者黑的招牌是荷叶宴，荷香餐厅本地人都认这家，点单照攻略不踩雷。","addr":"天鹅湖边"},{"title":"丘北辣椒鸡（人均58元）","description":"文山 · 普者黑的招牌是丘北辣椒鸡，辣椒主题馆本地人都认这家，点单照攻略不踩雷。","addr":"丘北县城"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":2245,"required":false},{"name":"住宿参考","amount":1746,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["换洗衣物与外套（早晚温差）","轻便雨衣或折叠伞","常用药品（肠胃药/创可贴）","墨镜与拍照道具","舒适徒步鞋（防滑鞋底）","防晒霜与遮阳帽","身份证件与手机充电宝","保温水杯与少量现金"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["高原地区避免剧烈运动，备好氧气瓶","贵重物品随身携带，景区人多注意","涉水项目穿好救生衣，听从工作人员安排","山区信号弱，提前下载离线地图"],"faqs":[["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["几月份去 文山 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["到达 文山 的交通方便吗？","推荐先到 文山，再打车或景区直通车前往核心景区；自驾导航直接搜普者黑即可。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"]]}',2,'这一次，把心跳交给山野。','on');
INSERT INTO `travel_route` (`id`,`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES (1153,'大熊猫基地都江堰纯攻略·臻享版27','guide','四川 · 成都','food','https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80',4990,2495,3,'大熊猫繁育研究基地 / 都江堰 / 南桥夜啤酒 —— 深度攻略助你玩透大熊猫基地都江堰精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「大熊猫基地都江堰」两日慢旅行——美食。郫县豆瓣是川菜之魂。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"四川 · 成都"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴成都","description":"集合出发，大巴直达大熊猫基地都江堰，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"大熊猫繁育研究基地","description":"抵达后首游大熊猫繁育研究基地，早8点开园直奔月亮产房，熊猫最活跃。","addr":"成华区外北熊猫大道","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐火锅（人均110元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"都江堰","description":"早起人少，都江堰精华时段，鱼嘴分水飞沙堰宝瓶口，古人智慧震撼。","addr":"都江堰市公园路","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐串串香，人均65元，补充体力。","addr":"玉林路","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"南桥夜啤酒","description":"午后游览南桥夜啤酒，岷江水上的夜风与美食。","addr":"都江堰市南桥","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"大熊猫繁育研究基地","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"大熊猫繁育研究基地是大熊猫基地都江堰最有代表性的看点，早8点开园直奔月亮产房，熊猫最活跃。攻略把它排进主线，时间留得最足。","notice":"早8点开园直奔月亮产房，熊猫最活跃。这个点位上午光线最好。","durationMinutes":240,"addr":"成华区外北熊猫大道"},{"spotId":"S2","