INSERT INTO `travel_route` (`id`,`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES (1154,'九寨沟纯攻略·臻享版28','guide','四川 · 阿坝','water','https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80',4990,2495,2,'五花海 / 诺日朗瀑布 / 长海 —— 深度攻略助你玩透九寨沟精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「九寨沟」三日深度游——水景。九寨沟牦牛酸奶值得尝。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"四川 · 阿坝"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往阿坝，抵达后办理入住、熟悉周边环境。","addr":"阿坝市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"五花海","description":"下午首站五花海，调整状态进入旅行节奏，九寨精华，孔雀河道顺光最美。","addr":"九寨沟县漳扎镇","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游阿坝一带氛围拉满，晚餐牦牛肉汤锅人均78元。","addr":"漳扎镇","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"诺日朗瀑布","description":"全天主景点诺日朗瀑布，中国最宽钙华瀑布。","addr":"九寨沟中心站","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐青稞酒（人均30元），早点休息。","addr":"藏寨","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"长海","description":"收官长海，最大海子，雪山倒影。","addr":"九寨沟则查洼沟","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐糌粑后集合返程，三日旅程圆满。","addr":"树正寨","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"五花海","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"五花海是九寨沟最有代表性的看点，九寨精华，孔雀河道顺光最美。攻略把它排进主线，时间留得最足。","notice":"九寨精华，孔雀河道顺光最美。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"九寨沟县漳扎镇"},{"spotId":"S2","name":"诺日朗瀑布","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"诺日朗瀑布是九寨沟最有代表性的看点，中国最宽钙华瀑布。攻略把它排进主线，时间留得最足。","notice":"中国最宽钙华瀑布。提前10分钟到，避开旅行团大部队。","durationMinutes":60,"addr":"九寨沟中心站"},{"spotId":"S3","name":"长海","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"长海是九寨沟最有代表性的看点，最大海子，雪山倒影。攻略把它排进主线，时间留得最足。","notice":"最大海子，雪山倒影。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"九寨沟则查洼沟"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"牦牛肉汤锅（人均78元）","description":"阿坝 · 九寨沟的招牌是牦牛肉汤锅，沟口藏家本地人都认这家，点单照攻略不踩雷。","addr":"漳扎镇"},{"title":"青稞酒（人均30元）","description":"阿坝 · 九寨沟的招牌是青稞酒，藏家体验本地人都认这家，点单照攻略不踩雷。","addr":"藏寨"},{"title":"糌粑（人均20元）","description":"阿坝 · 九寨沟的招牌是糌粑，藏族人家本地人都认这家，点单照攻略不踩雷。","addr":"树正寨"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":2245,"required":false},{"name":"住宿参考","amount":1746,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["常用药品（肠胃药/创可贴）","少量零食补给","墨镜与拍照道具","防晒霜与遮阳帽","换洗衣物与外套（早晚温差）","身份证件与手机充电宝","轻便雨衣或折叠伞","舒适徒步鞋（防滑鞋底）"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["高原地区避免剧烈运动，备好氧气瓶","看好同行老人小孩，走失原地等待","饮食注意卫生，海鲜过敏提前告知店家","贵重物品随身携带，景区人多注意"],"faqs":[["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"]]}',2,'慢一点，风景才来得及认识你。','on');
INSERT INTO `travel_route` (`id`,`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES (1155,'稻城亚丁纯攻略·臻享版29','guide','四川 · 甘孜','plateau','https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80',4990,2495,2,'牛奶海 / 五色海 / 冲古寺草坪 —— 深度攻略助你玩透稻城亚丁精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「稻城亚丁」两日慢旅行——高原。高原反应别逞强慢慢走。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"四川 · 甘孜"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴甘孜","description":"集合出发，大巴直达稻城亚丁，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"牛奶海","description":"抵达后首游牛奶海，海拔4600，马帮或徒步，量力而行。","addr":"稻城县香格里拉镇","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐松茸炖鸡（人均128元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"五色海","description":"早起人少，五色海精华时段，最后一百步最陡，景色值得。","addr":"牛奶海上方","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐酥油茶，人均15元，补充体力。","addr":"香格里拉镇","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"冲古寺草坪","description":"午后游览冲古寺草坪，仙乃日倒影机位。","addr":"亚丁村","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"牛奶海","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"牛奶海是稻城亚丁最有代表性的看点，海拔4600，马帮或徒步，量力而行。攻略把它排进主线，时间留得最足。","notice":"海拔4600，马帮或徒步，量力而行。周边有休息区与补给点，随时停留。","durationMinutes":360,"addr":"稻城县香格里拉镇"},{"spotId":"S2","name":"五色海","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"五色海是稻城亚丁最有代表性的看点，最后一百步最陡，景色值得。攻略把它排进主线，时间留得最足。","notice":"最后一百步最陡，景色值得。提前10分钟到，避开旅行团大部队。","durationMinutes":60,"addr":"牛奶海上方"},{"spotId":"S3","name":"冲古寺草坪","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"冲古寺草坪是稻城亚丁最有代表性的看点，仙乃日倒影机位。攻略把它排进主线，时间留得最足。","notice":"仙乃日倒影机位。这个点位上午光线最好。","durationMinutes":90,"addr":"亚丁村"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"松茸炖鸡（人均128元）","description":"甘孜 · 稻城亚丁的招牌是松茸炖鸡，亚丁村民宿本地人都认这家，点单照攻略不踩雷。","addr":"亚丁村"},{"title":"酥油茶（人均15元）","description":"甘孜 · 稻城亚丁的招牌是酥油茶，藏家小屋本地人都认这家，点单照攻略不踩雷。","addr":"香格里拉镇"},{"title":"高原土豆（人均10元）","description":"甘孜 · 稻城亚丁的招牌是高原土豆，小卖部熟食本地人都认这家，点单照攻略不踩雷。","addr":"洛绒牛场补给点"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":2245,"required":false},{"name":"住宿参考","amount":1746,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["保温水杯与少量现金","舒适徒步鞋（防滑鞋底）","身份证件与手机充电宝","常用药品（肠胃药/创可贴）","换洗衣物与外套（早晚温差）","轻便雨衣或折叠伞","墨镜与拍照道具","少量零食补给"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["看好同行老人小孩，走失原地等待","贵重物品随身携带，景区人多注意","夜间出行结伴，走主路不抄小道","恶劣天气听从景区安排，不进入未开放区域"],"faqs":[["当地有什么必吃？","到了 甘孜，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["几月份去 甘孜 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"]]}',2,'今天的夕阳，为你的抵达打光。','on');
INSERT INTO `travel_route` (`id`,`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES (1156,'峨眉山乐山大佛纯攻略·臻享版30','guide','四川 · 乐山','mountain','https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80',4990,2495,2,'乐山大佛 / 峨眉山金顶 / 清音阁 —— 深度攻略助你玩透峨眉山乐山大佛精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「峨眉山乐山大佛」三日深度游——山岳。峨眉雪芽茶清甜回甘。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"四川 · 乐山"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往乐山，抵达后办理入住、熟悉周边环境。","addr":"乐山市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"乐山大佛","description":"下午首站乐山大佛，调整状态进入旅行节奏，九曲栈道近距离看大佛脚背。","addr":"乐山市凌云路","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游乐山一带氛围拉满，晚餐钵钵鸡人均35元。","addr":"乐山港","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"峨眉山金顶","description":"全天主景点峨眉山金顶，十方普贤金像，云海日出。","addr":"峨眉山市","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐甜皮鸭（人均28元），早点休息。","addr":"乐山张公桥","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"清音阁","description":"收官清音阁，双桥清音，平路好走。","addr":"峨眉山低山区","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐豆腐脑后集合返程，三日旅程圆满。","addr":"峨眉市区","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"乐山大佛","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"乐山大佛是峨眉山乐山大佛最有代表性的看点，九曲栈道近距离看大佛脚背。攻略把它排进主线，时间留得最足。","notice":"九曲栈道近距离看大佛脚背。这个点位上午光线最好。","durationMinutes":180,"addr":"乐山市凌云路"},{"spotId":"S2","name":"峨眉山金顶","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"峨眉山金顶是峨眉山乐山大佛最有代表性的看点，十方普贤金像，云海日出。攻略把它排进主线，时间留得最足。","notice":"十方普贤金像，云海日出。周边有休息区与补给点，随时停留。","durationMinutes":300,"addr":"峨眉山市"},{"spotId":"S3","name":"清音阁","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"清音阁是峨眉山乐山大佛最有代表性的看点，双桥清音，平路好走。攻略把它排进主线，时间留得最足。","notice":"双桥清音，平路好走。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"峨眉山低山区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"钵钵鸡（人均35元）","description":"乐山 · 峨眉山乐山大佛的招牌是钵钵鸡，叶婆婆本地人都认这家，点单照攻略不踩雷。","addr":"乐山港"},{"title":"甜皮鸭（人均28元）","description":"乐山 · 峨眉山乐山大佛的招牌是甜皮鸭，赵鸭子本地人都认这家，点单照攻略不踩雷。","addr":"乐山张公桥"},{"title":"豆腐脑（人均12元）","description":"乐山 · 峨眉山乐山大佛的招牌是豆腐脑，峨眉豆腐脑本地人都认这家，点单照攻略不踩雷。","addr":"峨眉市区"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":2245,"required":false},{"name":"住宿参考","amount":1746,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["换洗衣物与外套（早晚温差）","舒适徒步鞋（防滑鞋底）","常用药品（肠胃药/创可贴）","保温水杯与少量现金","轻便雨衣或折叠伞","身份证件与手机充电宝","少量零食补给","墨镜与拍照道具"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["山区信号弱，提前下载离线地图","看好同行老人小孩，走失原地等待","高原地区避免剧烈运动，备好氧气瓶","恶劣天气听从景区安排，不进入未开放区域"],"faqs":[["到达 乐山 的交通方便吗？","推荐先到 乐山，再打车或景区直通车前往核心景区；自驾导航直接搜峨眉山乐山大佛即可。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["几月份去 乐山 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"]]}',2,'山高水长，都是给你准备的惊喜。','on');
INSERT INTO `travel_route` (`id`,`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES (1157,'阆中古城纯攻略·臻享版31','guide','四川 · 南充','ancient_town','https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80',4990,2495,1,'阆中古城 / 华光楼 / 锦屏山 —— 深度攻略助你玩透阆中古城精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「阆中古城」两日慢旅行——古镇。保宁醋是四大名醋之一。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"四川 · 南充"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴南充","description":"集合出发，大巴直达阆中古城，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"阆中古城","description":"抵达后首游阆中古城，四大古城之一，张飞庙贡院联票。","addr":"南充市阆中市","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐张飞牛肉（人均45元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"华光楼","description":"早起人少，华光楼精华时段，登楼看嘉陵江三面环抱。","addr":"古城上华街","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐保宁醋，人均20元，补充体力。","addr":"古城内","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"锦屏山","description":"午后游览锦屏山，观古城全景最佳位。","addr":"古城对岸","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"阆中古城","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"阆中古城是阆中古城最有代表性的看点，四大古城之一，张飞庙贡院联票。攻略把它排进主线，时间留得最足。","notice":"四大古城之一，张飞庙贡院联票。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"南充市阆中市"},{"spotId":"S2","name":"华光楼","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"华光楼是阆中古城最有代表性的看点，登楼看嘉陵江三面环抱。攻略把它排进主线，时间留得最足。","notice":"登楼看嘉陵江三面环抱。周边有休息区与补给点，随时停留。","durationMinutes":60,"addr":"古城上华街"},{"spotId":"S3","name":"锦屏山","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"锦屏山是阆中古城最有代表性的看点，观古城全景最佳位。攻略把它排进主线，时间留得最足。","notice":"观古城全景最佳位。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"古城对岸"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"张飞牛肉（人均45元）","description":"南充 · 阆中古城的招牌是张飞牛肉，张飞牛肉旗舰店本地人都认这家，点单照攻略不踩雷。","addr":"古城北街"},{"title":"保宁醋（人均20元）","description":"南充 · 阆中古城的招牌是保宁醋，醋文化博览馆本地人都认这家，点单照攻略不踩雷。","addr":"古城内"},{"title":"油香（人均8元）","description":"南充 · 阆中古城的招牌是油香，古城小吃摊本地人都认这家，点单照攻略不踩雷。","addr":"下沙河街"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":2245,"required":false},{"name":"住宿参考","amount":1746,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["墨镜与拍照道具","常用药品（肠胃药/创可贴）","舒适徒步鞋（防滑鞋底）","换洗衣物与外套（早晚温差）","身份证件与手机充电宝","少量零食补给","防晒霜与遮阳帽","保温水杯与少量现金"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["山区信号弱，提前下载离线地图","涉水项目穿好救生衣，听从工作人员安排","夜间出行结伴，走主路不抄小道","看好同行老人小孩，走失原地等待"],"faqs":[["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["到达 南充 的交通方便吗？","推荐先到 南充，再打车或景区直通车前往核心景区；自驾导航直接搜阆中古城即可。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"]]}',2,'这一程，山水都在替你说话。','on');
INSERT INTO `travel_route` (`id`,`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES (1158,'四姑娘山纯攻略·臻享版32','guide','四川 · 阿坝','mountain','https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80',4990,2495,2,'双桥沟 / 长坪沟 / 猫鼻梁 —— 深度攻略助你玩透四姑娘山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「四姑娘山」三日深度游——山岳。四姑娘山沙棘汁酸爽提神。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"四川 · 阿坝"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往阿坝，抵达后办理入住、熟悉周边环境。","addr":"阿坝市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"双桥沟","description":"下午首站双桥沟，调整状态进入旅行节奏，坐观光车看雪山峡谷，最省力。","addr":"四姑娘山镇","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游阿坝一带氛围拉满，晚餐藏式火锅人均78元。","addr":"四姑娘山镇","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"长坪沟","description":"全天主景点长坪沟，木栈道进山，幺妹峰侧面。","addr":"四姑娘山镇","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐牦牛肉干（人均45元），早点休息。","addr":"镇主街","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"猫鼻梁","description":"收官猫鼻梁，四峰全景最佳机位。","addr":"去四姑娘山路途","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐酥油茶后集合返程，三日旅程圆满。","addr":"长坪沟口","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"双桥沟","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"双桥沟是四姑娘山最有代表性的看点，坐观光车看雪山峡谷，最省力。攻略把它排进主线，时间留得最足。","notice":"坐观光车看雪山峡谷，最省力。提前10分钟到，避开旅行团大部队。","durationMinutes":240,"addr":"四姑娘山镇"},{"spotId":"S2","name":"长坪沟","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"长坪沟是四姑娘山最有代表性的看点，木栈道进山，幺妹峰侧面。攻略把它排进主线，时间留得最足。","notice":"木栈道进山，幺妹峰侧面。周边有休息区与补给点，随时停留。","durationMinutes":240,"addr":"四姑娘山镇"},{"spotId":"S3","name":"猫鼻梁","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"猫鼻梁是四姑娘山最有代表性的看点，四峰全景最佳机位。攻略把它排进主线，时间留得最足。","notice":"四峰全景最佳机位。周边有休息区与补给点，随时停留。","durationMinutes":30,"addr":"去四姑娘山路途"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"藏式火锅（人均78元）","description":"阿坝 · 四姑娘山的招牌是藏式火锅，日隆镇餐馆本地人都认这家，点单照攻略不踩雷。","addr":"四姑娘山镇"},{"title":"牦牛肉干（人均45元）","description":"阿坝 · 四姑娘山的招牌是牦牛肉干，特产店本地人都认这家，点单照攻略不踩雷。","addr":"镇主街"},{"title":"酥油茶（人均15元）","description":"阿坝 · 四姑娘山的招牌是酥油茶，藏家茶馆本地人都认这家，点单照攻略不踩雷。","addr":"长坪沟口"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":2245,"required":false},{"name":"住宿参考","amount":1746,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["少量零食补给","防晒霜与遮阳帽","轻便雨衣或折叠伞","保温水杯与少量现金","墨镜与拍照道具","常用药品（肠胃药/创可贴）","身份证件与手机充电宝","舒适徒步鞋（防滑鞋底）"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","看好同行老人小孩，走失原地等待","夜间出行结伴，走主路不抄小道","贵重物品随身携带，景区人多注意"],"faqs":[["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["当地有什么必吃？","到了 阿坝，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["几月份去 阿坝 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"]]}',2,'出发这一刻，惊喜已经在路上。','on');
INSERT INTO `travel_route` (`id`,`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES (1159,'蜀南竹海纯攻略·臻享版33','guide','四川 · 宜宾','village','https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80',4990,2495,1,'蜀南竹海 / 李庄古镇 / 兴文石海 —— 深度攻略助你玩透蜀南竹海精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「蜀南竹海」两日慢旅行——古村落。竹荪竹笋干货轻便。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"四川 · 宜宾"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴宜宾","description":"集合出发，大巴直达蜀南竹海，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"蜀南竹海","description":"抵达后首游蜀南竹海，忘忧谷翡翠长廊，竹林深处人家。","addr":"宜宾市长宁县","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐全竹宴（人均68元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"李庄古镇","description":"早起人少，李庄古镇精华时段，万里长江第一古镇，抗战文化。","addr":"翠屏区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐李庄白肉，人均42元，补充体力。","addr":"李庄古镇","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"兴文石海","description":"午后游览兴文石海，天坑石林与僰人文化。","addr":"兴文县","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"蜀南竹海","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"蜀南竹海是蜀南竹海最有代表性的看点，忘忧谷翡翠长廊，竹林深处人家。攻略把它排进主线，时间留得最足。","notice":"忘忧谷翡翠长廊，竹林深处人家。拍照记得留神脚下台阶。","durationMinutes":240,"addr":"宜宾市长宁县"},{"spotId":"S2","name":"李庄古镇","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"李庄古镇是蜀南竹海最有代表性的看点，万里长江第一古镇，抗战文化。攻略把它排进主线，时间留得最足。","notice":"万里长江第一古镇，抗战文化。拍照记得留神脚下台阶。","durationMinutes":150,"addr":"翠屏区"},{"spotId":"S3","name":"兴文石海","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"兴文石海是蜀南竹海最有代表性的看点，天坑石林与僰人文化。攻略把它排进主线，时间留得最足。","notice":"天坑石林与僰人文化。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"兴文县"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"全竹宴（人均68元）","description":"宜宾 · 蜀南竹海的招牌是全竹宴，竹海人家本地人都认这家，点单照攻略不踩雷。","addr":"蜀南竹海"},{"title":"李庄白肉（人均42元）","description":"宜宾 · 蜀南竹海的招牌是李庄白肉，李庄老店本地人都认这家，点单照攻略不踩雷。","addr":"李庄古镇"},{"title":"燃面（人均12元）","description":"宜宾 · 蜀南竹海的招牌是燃面，刘臣街燃面本地人都认这家，点单照攻略不踩雷。","addr":"宜宾市区"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":2245,"required":false},{"name":"住宿参考","amount":1746,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["防晒霜与遮阳帽","墨镜与拍照道具","轻便雨衣或折叠伞","舒适徒步鞋（防滑鞋底）","相机或运动相机","换洗衣物与外套（早晚温差）","常用药品（肠胃药/创可贴）","保温水杯与少量现金"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["山区信号弱，提前下载离线地图","饮食注意卫生，海鲜过敏提前告知店家","恶劣天气听从景区安排，不进入未开放区域","看好同行老人小孩，走失原地等待"],"faqs":[["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["当地有什么必吃？","到了 宜宾，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"]]}',2,'把日常调成静音，听风与远方的声音。','on');
INSERT INTO `travel_route` (`id`,`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES (1160,'黄果树瀑布纯攻略·臻享版34','guide','贵州 · 安顺','water','https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80',4990,2495,2,'黄果树大瀑布 / 天星桥 / 陡坡塘 —— 深度攻略助你玩透黄果树瀑布精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「黄果树瀑布」三日深度游——水景。安顺三刀是传统名点。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"贵州 · 安顺"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往安顺，抵达后办理入住、熟悉周边环境。","addr":"安顺市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"黄果树大瀑布","description":"下午首站黄果树大瀑布，调整状态进入旅行节奏，亚洲最大瀑布，水帘洞穿瀑而过。","addr":"安顺市镇宁县","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游安顺一带氛围拉满，晚餐夺夺粉人均35元。","addr":"安顺市区","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"天星桥","description":"全天主景点天星桥，石景水上盆景，数生步趣味。","addr":"黄果树景区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐裹卷（人均12元），早点休息。","addr":"黄果树镇","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"陡坡塘","description":"收官陡坡塘，西游记片尾取景地。","addr":"黄果树景区","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐布依农家餐后集合返程，三日旅程圆满。","addr":"石头寨","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"黄果树大瀑布","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"黄果树大瀑布是黄果树瀑布最有代表性的看点，亚洲最大瀑布，水帘洞穿瀑而过。攻略把它排进主线，时间留得最足。","notice":"亚洲最大瀑布，水帘洞穿瀑而过。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"安顺市镇宁县"},{"spotId":"S2","name":"天星桥","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"天星桥是黄果树瀑布最有代表性的看点，石景水上盆景，数生步趣味。攻略把它排进主线，时间留得最足。","notice":"石景水上盆景，数生步趣味。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"黄果树景区"},{"spotId":"S3","name":"陡坡塘","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"陡坡塘是黄果树瀑布最有代表性的看点，西游记片尾取景地。攻略把它排进主线，时间留得最足。","notice":"西游记片尾取景地。提前10分钟到，避开旅行团大部队。","durationMinutes":60,"addr":"黄果树景区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"夺夺粉（人均35元）","description":"安顺 · 黄果树瀑布的招牌是夺夺粉，安顺小吃街本地人都认这家，点单照攻略不踩雷。","addr":"安顺市区"},{"title":"裹卷（人均12元）","description":"安顺 · 黄果树瀑布的招牌是裹卷，苗岭小吃本地人都认这家，点单照攻略不踩雷。","addr":"黄果树镇"},{"title":"布依农家餐（人均48元）","description":"安顺 · 黄果树瀑布的招牌是布依农家餐，石头寨本地人都认这家，点单照攻略不踩雷。","addr":"石头寨"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":2245,"required":false},{"name":"住宿参考","amount":1746,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["舒适徒步鞋（防滑鞋底）","保温水杯与少量现金","轻便雨衣或折叠伞","换洗衣物与外套（早晚温差）","墨镜与拍照道具","身份证件与手机充电宝","相机或运动相机","常用药品（肠胃药/创可贴）"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["饮食注意卫生，海鲜过敏提前告知店家","夜间出行结伴，走主路不抄小道","贵重物品随身携带，景区人多注意","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["到达 安顺 的交通方便吗？","推荐先到 安顺，再打车或景区直通车前往核心景区；自驾导航直接搜黄果树瀑布即可。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"]]}',2,'有些风景，照片永远差一点，比如你亲眼看到的那一刻。','on');
INSERT INTO `travel_route` (`id`,`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES (1161,'荔波小七孔纯攻略·臻享版35','guide','贵州 · 黔南','water','https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80',4990,2495,2,'小七孔古桥 / 卧龙潭 / 大七孔 —— 深度攻略助你玩透荔波小七孔精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「荔波小七孔」两日慢旅行——水景。荔波青梅制品酸甜开胃。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"贵州 · 黔南"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴黔南","description":"集合出发，大巴直达荔波小七孔，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"小七孔古桥","description":"抵达后首游小七孔古桥，68级跌水瀑布起点，绿宝石湖水。","addr":"荔波县小七孔镇","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐酸汤鱼（人均68元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"卧龙潭","description":"早起人少，卧龙潭精华时段，蓝到不真实的深潭，漂流出片。","addr":"小七孔景区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐杨梅汤，人均10元，补充体力。","addr":"小七孔镇","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"大七孔","description":"午后游览大七孔，天生桥鬼斧神工。","addr":"荔波县","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"小七孔古桥","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"小七孔古桥是荔波小七孔最有代表性的看点，68级跌水瀑布起点，绿宝石湖水。攻略把它排进主线，时间留得最足。","notice":"68级跌水瀑布起点，绿宝石湖水。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"荔波县小七孔镇"},{"spotId":"S2","name":"卧龙潭","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"卧龙潭是荔波小七孔最有代表性的看点，蓝到不真实的深潭，漂流出片。攻略把它排进主线，时间留得最足。","notice":"蓝到不真实的深潭，漂流出片。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"小七孔景区"},{"spotId":"S3","name":"大七孔","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"大七孔是荔波小七孔最有代表性的看点，天生桥鬼斧神工。攻略把它排进主线，时间留得最足。","notice":"天生桥鬼斧神工。这个点位上午光线最好。","durationMinutes":90,"addr":"荔波县"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"酸汤鱼（人均68元）","description":"黔南 · 荔波小七孔的招牌是酸汤鱼，凯里酸汤鱼本地人都认这家，点单照攻略不踩雷。","addr":"荔波县城"},{"title":"杨梅汤（人均10元）","description":"黔南 · 荔波小七孔的招牌是杨梅汤，街边饮品本地人都认这家，点单照攻略不踩雷。","addr":"小七孔镇"},{"title":"糯米排骨（人均42元）","description":"黔南 · 荔波小七孔的招牌是糯米排骨，布依农家本地人都认这家，点单照攻略不踩雷。","addr":"景区出口"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":2245,"required":false},{"name":"住宿参考","amount":1746,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["轻便雨衣或折叠伞","舒适徒步鞋（防滑鞋底）","常用药品（肠胃药/创可贴）","保温水杯与少量现金","身份证件与手机充电宝","墨镜与拍照道具","防晒霜与遮阳帽","少量零食补给"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["饮食注意卫生，海鲜过敏提前告知店家","涉水项目穿好救生衣，听从工作人员安排","夜间出行结伴，走主路不抄小道","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["几月份去 黔南 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["到达 黔南 的交通方便吗？","推荐先到 黔南，再打车或景区直通车前往核心景区；自驾导航直接搜荔波小七孔即可。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"]]}',2,'好运藏在出发的行囊里。','on');
INSERT INTO `travel_route` (`id`,`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES (1162,'西江千户苗寨纯攻略·臻享版36','guide','贵州 · 黔东南','village','https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80',5990,2995,1,'西江观景台 / 一号风雨桥 / 嘎歌古巷 —— 深度攻略助你玩透西江千户苗寨精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「西江千户苗寨」三日深度游——古村落。苗银手镯按克计价别按件。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"贵州 · 黔东南"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往黔东南，抵达后办理入住、熟悉周边环境。","addr":"黔东南市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"西江观景台","description":"下午首站西江观景台，调整状态进入旅行节奏，万家灯火夜景，天黑后1小时最佳。","addr":"雷山县西江镇","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游黔东南一带氛围拉满，晚餐苗家酸汤鱼人均68元。","addr":"西江主街","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"一号风雨桥","description":"全天主景点一号风雨桥，苗家歌舞表演互动。","addr":"西江苗寨","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐糯米饭（人均10元），早点休息。","addr":"风雨桥头","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"嘎歌古巷","description":"收官嘎歌古巷，非遗银饰刺绣工坊。","addr":"西江苗寨","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐米豆腐后集合返程，三日旅程圆满。","addr":"嘎歌古巷","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"西江观景台","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"西江观景台是西江千户苗寨最有代表性的看点，万家灯火夜景，天黑后1小时最佳。攻略把它排进主线，时间留得最足。","notice":"万家灯火夜景，天黑后1小时最佳。提前10