INSERT INTO `travel_route` (`id`,`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES (1163,'梵净山纯攻略·臻享版37','guide','贵州 · 铜仁','mountain','https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80',5990,2995,2,'红云金顶 / 蘑菇石 / 承恩寺 —— 深度攻略助你玩透梵净山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「梵净山」两日慢旅行——山岳。梵净山藤茶甘甜养人。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"贵州 · 铜仁"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴铜仁","description":"集合出发，大巴直达梵净山，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"红云金顶","description":"抵达后首游红云金顶，海拔2493双峰寺庙，爬铁索上天桥。","addr":"铜仁市江口县","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐江口豆腐干（人均28元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"蘑菇石","description":"早起人少，蘑菇石精华时段，10亿年奇石，排队打卡。","addr":"梵净山标志性景观","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐米虾，人均48元，补充体力。","addr":"太平镇","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"承恩寺","description":"午后游览承恩寺，明代古刹，云海时分最妙。","addr":"金顶下方","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"红云金顶","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"红云金顶是梵净山最有代表性的看点，海拔2493双峰寺庙，爬铁索上天桥。攻略把它排进主线，时间留得最足。","notice":"海拔2493双峰寺庙，爬铁索上天桥。这个点位上午光线最好。","durationMinutes":240,"addr":"铜仁市江口县"},{"spotId":"S2","name":"蘑菇石","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"蘑菇石是梵净山最有代表性的看点，10亿年奇石，排队打卡。攻略把它排进主线，时间留得最足。","notice":"10亿年奇石，排队打卡。周边有休息区与补给点，随时停留。","durationMinutes":60,"addr":"梵净山标志性景观"},{"spotId":"S3","name":"承恩寺","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"承恩寺是梵净山最有代表性的看点，明代古刹，云海时分最妙。攻略把它排进主线，时间留得最足。","notice":"明代古刹，云海时分最妙。这个点位上午光线最好。","durationMinutes":60,"addr":"金顶下方"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"江口豆腐干（人均28元）","description":"铜仁 · 梵净山的招牌是江口豆腐干，山脚农家本地人都认这家，点单照攻略不踩雷。","addr":"梵净山镇"},{"title":"米虾（人均48元）","description":"铜仁 · 梵净山的招牌是米虾，河鲜馆本地人都认这家，点单照攻略不踩雷。","addr":"太平镇"},{"title":"天麻炖鸡（人均88元）","description":"铜仁 · 梵净山的招牌是天麻炖鸡，药膳馆本地人都认这家，点单照攻略不踩雷。","addr":"江口县城"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":2695,"required":false},{"name":"住宿参考","amount":2096,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["舒适徒步鞋（防滑鞋底）","少量零食补给","保温水杯与少量现金","换洗衣物与外套（早晚温差）","身份证件与手机充电宝","相机或运动相机","防晒霜与遮阳帽","墨镜与拍照道具"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["贵重物品随身携带，景区人多注意","看好同行老人小孩，走失原地等待","山区信号弱，提前下载离线地图","恶劣天气听从景区安排，不进入未开放区域"],"faqs":[["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"]]}',2,'远方的炊烟，是写给旅人的信。','on');
INSERT INTO `travel_route` (`id`,`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES (1164,'镇远古镇纯攻略·臻享版38','guide','贵州 · 黔东南','ancient_town','https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80',5990,2995,1,'青龙洞 / 舞阳河 / 石屏山 —— 深度攻略助你玩透镇远古镇精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「镇远古镇」三日深度游——古镇。镇远蓝染布艺越洗越好看。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"贵州 · 黔东南"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往黔东南，抵达后办理入住、熟悉周边环境。","addr":"黔东南市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"青龙洞","description":"下午首站青龙洞，调整状态进入旅行节奏，贴崖古建筑群，对望古城。","addr":"镇远县中和山","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游黔东南一带氛围拉满，晚餐酸汤鱼人均58元。","addr":"兴隆街","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"舞阳河","description":"全天主景点舞阳河，乘船看孔雀开屏峰。","addr":"镇远县","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐陈年道菜（人均30元），早点休息。","addr":"古镇主街","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"石屏山","description":"收官石屏山，俯瞰太极古城全景。","addr":"古城北侧","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐苗家腊肉后集合返程，三日旅程圆满。","addr":"舞阳河畔","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"青龙洞","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"青龙洞是镇远古镇最有代表性的看点，贴崖古建筑群，对望古城。攻略把它排进主线，时间留得最足。","notice":"贴崖古建筑群，对望古城。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"镇远县中和山"},{"spotId":"S2","name":"舞阳河","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"舞阳河是镇远古镇最有代表性的看点，乘船看孔雀开屏峰。攻略把它排进主线，时间留得最足。","notice":"乘船看孔雀开屏峰。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"镇远县"},{"spotId":"S3","name":"石屏山","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"石屏山是镇远古镇最有代表性的看点，俯瞰太极古城全景。攻略把它排进主线，时间留得最足。","notice":"俯瞰太极古城全景。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"古城北侧"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"酸汤鱼（人均58元）","description":"黔东南 · 镇远古镇的招牌是酸汤鱼，古城酸汤馆本地人都认这家，点单照攻略不踩雷。","addr":"兴隆街"},{"title":"陈年道菜（人均30元）","description":"黔东南 · 镇远古镇的招牌是陈年道菜，老字号本地人都认这家，点单照攻略不踩雷。","addr":"古镇主街"},{"title":"苗家腊肉（人均48元）","description":"黔东南 · 镇远古镇的招牌是苗家腊肉，河畔农家本地人都认这家，点单照攻略不踩雷。","addr":"舞阳河畔"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":2695,"required":false},{"name":"住宿参考","amount":2096,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["换洗衣物与外套（早晚温差）","相机或运动相机","常用药品（肠胃药/创可贴）","墨镜与拍照道具","身份证件与手机充电宝","少量零食补给","保温水杯与少量现金","防晒霜与遮阳帽"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["贵重物品随身携带，景区人多注意","饮食注意卫生，海鲜过敏提前告知店家","看好同行老人小孩，走失原地等待","涉水项目穿好救生衣，听从工作人员安排"],"faqs":[["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"]]}',2,'慢一点，风景才来得及认识你。','on');
INSERT INTO `travel_route` (`id`,`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES (1165,'乌蒙大草原纯攻略·臻享版39','guide','贵州 · 六盘水','camp','https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80',5990,2995,10,'乌蒙大草原 / 野玉海 / 娘娘山 —— 深度攻略助你玩透乌蒙大草原精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「乌蒙大草原」两日慢旅行——露营地。六盘水刺梨维C之王。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"贵州 · 六盘水"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴六盘水","description":"集合出发，大巴直达乌蒙大草原，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"乌蒙大草原","description":"抵达后首游乌蒙大草原，云上花海佛光，露营星空。","addr":"六盘水市盘州市","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐水城烙锅（人均45元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"野玉海","description":"早起人少，野玉海精华时段，海坪彝族小镇与观光小火车。","addr":"水城区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐羊肉粉，人均15元，补充体力。","addr":"盘州市","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"娘娘山","description":"午后游览娘娘山，高原湿地与温泉。","addr":"盘州市","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"乌蒙大草原","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"乌蒙大草原是乌蒙大草原最有代表性的看点，云上花海佛光，露营星空。攻略把它排进主线，时间留得最足。","notice":"云上花海佛光，露营星空。这个点位上午光线最好。","durationMinutes":180,"addr":"六盘水市盘州市"},{"spotId":"S2","name":"野玉海","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"野玉海是乌蒙大草原最有代表性的看点，海坪彝族小镇与观光小火车。攻略把它排进主线，时间留得最足。","notice":"海坪彝族小镇与观光小火车。提前10分钟到，避开旅行团大部队。","durationMinutes":150,"addr":"水城区"},{"spotId":"S3","name":"娘娘山","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"娘娘山是乌蒙大草原最有代表性的看点，高原湿地与温泉。攻略把它排进主线，时间留得最足。","notice":"高原湿地与温泉。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"盘州市"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"水城烙锅（人均45元）","description":"六盘水 · 乌蒙大草原的招牌是水城烙锅，烙锅一条街本地人都认这家，点单照攻略不踩雷。","addr":"水城区"},{"title":"羊肉粉（人均15元）","description":"六盘水 · 乌蒙大草原的招牌是羊肉粉，元坤羊肉粉本地人都认这家，点单照攻略不踩雷。","addr":"盘州市"},{"title":"刺梨汁（人均10元）","description":"六盘水 · 乌蒙大草原的招牌是刺梨汁，维C宝饮品本地人都认这家，点单照攻略不踩雷。","addr":"全区通用"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":2695,"required":false},{"name":"住宿参考","amount":2096,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["相机或运动相机","身份证件与手机充电宝","常用药品（肠胃药/创可贴）","少量零食补给","舒适徒步鞋（防滑鞋底）","换洗衣物与外套（早晚温差）","轻便雨衣或折叠伞","防晒霜与遮阳帽"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["饮食注意卫生，海鲜过敏提前告知店家","贵重物品随身携带，景区人多注意","涉水项目穿好救生衣，听从工作人员安排","山区信号弱，提前下载离线地图"],"faqs":[["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["当地有什么必吃？","到了 六盘水，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["到达 六盘水 的交通方便吗？","推荐先到 六盘水，再打车或景区直通车前往核心景区；自驾导航直接搜乌蒙大草原即可。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"]]}',2,'今天的夕阳，为你的抵达打光。','on');
INSERT INTO `travel_route` (`id`,`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES (1166,'阳朔漓江纯攻略·臻享版40','guide','广西 · 桂林','water','https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80',5990,2995,2,'兴坪漓江 / 遇龙河 / 西街 —— 深度攻略助你玩透阳朔漓江精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「阳朔漓江」三日深度游——水景。阳朔金桔个大超甜。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"广西 · 桂林"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往桂林，抵达后办理入住、熟悉周边环境。","addr":"桂林市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"兴坪漓江","description":"下午首站兴坪漓江，调整状态进入旅行节奏，20元人民币背景，老寨山看全景。","addr":"阳朔县兴坪镇","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游桂林一带氛围拉满，晚餐啤酒鱼人均68元。","addr":"西街口","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"遇龙河","description":"全天主景点遇龙河，竹筏漂流，工农桥日落。","addr":"阳朔县遇龙河","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐桂林米粉（人均12元），早点休息。","addr":"兴坪老街","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"西街","description":"收官西街，老外扎堆的千年老街。","addr":"阳朔县西街","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐田螺酿后集合返程，三日旅程圆满。","addr":"遇龙河边","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"兴坪漓江","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"兴坪漓江是阳朔漓江最有代表性的看点，20元人民币背景，老寨山看全景。攻略把它排进主线，时间留得最足。","notice":"20元人民币背景，老寨山看全景。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"阳朔县兴坪镇"},{"spotId":"S2","name":"遇龙河","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"遇龙河是阳朔漓江最有代表性的看点，竹筏漂流，工农桥日落。攻略把它排进主线，时间留得最足。","notice":"竹筏漂流，工农桥日落。这个点位上午光线最好。","durationMinutes":180,"addr":"阳朔县遇龙河"},{"spotId":"S3","name":"西街","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"西街是阳朔漓江最有代表性的看点，老外扎堆的千年老街。攻略把它排进主线，时间留得最足。","notice":"老外扎堆的千年老街。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"阳朔县西街"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"啤酒鱼（人均68元）","description":"桂林 · 阳朔漓江的招牌是啤酒鱼，谢大姐啤酒鱼本地人都认这家，点单照攻略不踩雷。","addr":"西街口"},{"title":"桂林米粉（人均12元）","description":"桂林 · 阳朔漓江的招牌是桂林米粉，崇善米粉本地人都认这家，点单照攻略不踩雷。","addr":"兴坪老街"},{"title":"田螺酿（人均38元）","description":"桂林 · 阳朔漓江的招牌是田螺酿，阳朔农家本地人都认这家，点单照攻略不踩雷。","addr":"遇龙河边"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":2695,"required":false},{"name":"住宿参考","amount":2096,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["轻便雨衣或折叠伞","少量零食补给","防晒霜与遮阳帽","墨镜与拍照道具","舒适徒步鞋（防滑鞋底）","常用药品（肠胃药/创可贴）","换洗衣物与外套（早晚温差）","身份证件与手机充电宝"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","涉水项目穿好救生衣，听从工作人员安排","山区信号弱，提前下载离线地图","贵重物品随身携带，景区人多注意"],"faqs":[["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["几月份去 桂林 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"]]}',2,'山高水长，都是给你准备的惊喜。','on');
INSERT INTO `travel_route` (`id`,`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES (1167,'龙脊梯田纯攻略·臻享版41','guide','广西 · 桂林','village','https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80',5990,2995,1,'平安寨七星伴月 / 金坑大寨 / 黄洛红瑶寨 —— 深度攻略助你玩透龙脊梯田精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「龙脊梯田」两日慢旅行——古村落。龙脊辣椒酱拌饭一绝。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"广西 · 桂林"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴桂林","description":"集合出发，大巴直达龙脊梯田，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"平安寨七星伴月","description":"抵达后首游平安寨七星伴月，经典梯田观景台，徒步30分钟。","addr":"龙胜县龙脊镇","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐竹筒饭（人均25元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"金坑大寨","description":"早起人少，金坑大寨精华时段，缆车直达3号观景点，日落最佳。","addr":"龙脊梯田金坑","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐土鸡煲，人均68元，补充体力。","addr":"金坑梯田","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"黄洛红瑶寨","description":"午后游览黄洛红瑶寨，天下第一长发村表演。","addr":"龙脊山下","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"平安寨七星伴月","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"平安寨七星伴月是龙脊梯田最有代表性的看点，经典梯田观景台，徒步30分钟。攻略把它排进主线，时间留得最足。","notice":"经典梯田观景台，徒步30分钟。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"龙胜县龙脊镇"},{"spotId":"S2","name":"金坑大寨","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"金坑大寨是龙脊梯田最有代表性的看点，缆车直达3号观景点，日落最佳。攻略把它排进主线，时间留得最足。","notice":"缆车直达3号观景点，日落最佳。拍照记得留神脚下台阶。","durationMinutes":150,"addr":"龙脊梯田金坑"},{"spotId":"S3","name":"黄洛红瑶寨","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"黄洛红瑶寨是龙脊梯田最有代表性的看点，天下第一长发村表演。攻略把它排进主线，时间留得最足。","notice":"天下第一长发村表演。这个点位上午光线最好。","durationMinutes":60,"addr":"龙脊山下"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"竹筒饭（人均25元）","description":"桂林 · 龙脊梯田的招牌是竹筒饭，梯田农家本地人都认这家，点单照攻略不踩雷。","addr":"平安寨"},{"title":"土鸡煲（人均68元）","description":"桂林 · 龙脊梯田的招牌是土鸡煲，大寨农家本地人都认这家，点单照攻略不踩雷。","addr":"金坑梯田"},{"title":"龙脊茶（人均20元）","description":"桂林 · 龙脊梯田的招牌是龙脊茶，茶农家本地人都认这家，点单照攻略不踩雷。","addr":"黄洛瑶寨"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":2695,"required":false},{"name":"住宿参考","amount":2096,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["保温水杯与少量现金","墨镜与拍照道具","身份证件与手机充电宝","相机或运动相机","舒适徒步鞋（防滑鞋底）","少量零食补给","轻便雨衣或折叠伞","换洗衣物与外套（早晚温差）"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","高原地区避免剧烈运动，备好氧气瓶","看好同行老人小孩，走失原地等待","涉水项目穿好救生衣，听从工作人员安排"],"faqs":[["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"]]}',2,'这一程，山水都在替你说话。','on');
INSERT INTO `travel_route` (`id`,`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES (1168,'涠洲岛纯攻略·臻享版42','guide','广西 · 北海','sea','https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80',5990,2995,6,'鳄鱼山火山公园 / 五彩滩 / 滴水丹屏 —— 深度攻略助你玩透涠洲岛精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「涠洲岛」三日深度游——海滨。涠洲岛香蕉又软又甜。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"广西 · 北海"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往北海，抵达后办理入住、熟悉周边环境。","addr":"北海市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"鳄鱼山火山公园","description":"下午首站鳄鱼山火山公园，调整状态进入旅行节奏，火山地质地貌，灯塔海景。","addr":"涠洲岛南湾","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游北海一带氛围拉满，晚餐海鲜大餐人均98元。","addr":"南湾街","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"五彩滩","description":"全天主景点五彩滩，退潮时火山岩纹理最美。","addr":"涠洲岛东岸","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐香蕉猪（人均58元），早点休息。","addr":"滴水村","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"滴水丹屏","description":"收官滴水丹屏，日落圣地，海水退潮捡贝壳。","addr":"涠洲岛西侧","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐椰子冻后集合返程，三日旅程圆满。","addr":"南湾夜市","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"鳄鱼山火山公园","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"鳄鱼山火山公园是涠洲岛最有代表性的看点，火山地质地貌，灯塔海景。攻略把它排进主线，时间留得最足。","notice":"火山地质地貌，灯塔海景。这个点位上午光线最好。","durationMinutes":180,"addr":"涠洲岛南湾"},{"spotId":"S2","name":"五彩滩","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"五彩滩是涠洲岛最有代表性的看点，退潮时火山岩纹理最美。攻略把它排进主线，时间留得最足。","notice":"退潮时火山岩纹理最美。这个点位上午光线最好。","durationMinutes":90,"addr":"涠洲岛东岸"},{"spotId":"S3","name":"滴水丹屏","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"滴水丹屏是涠洲岛最有代表性的看点，日落圣地，海水退潮捡贝壳。攻略把它排进主线，时间留得最足。","notice":"日落圣地，海水退潮捡贝壳。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"涠洲岛西侧"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"海鲜大餐（人均98元）","description":"北海 · 涠洲岛的招牌是海鲜大餐，南湾海鲜市场加工本地人都认这家，点单照攻略不踩雷。","addr":"南湾街"},{"title":"香蕉猪（人均58元）","description":"北海 · 涠洲岛的招牌是香蕉猪，岛民农家本地人都认这家，点单照攻略不踩雷。","addr":"滴水村"},{"title":"椰子冻（人均15元）","description":"北海 · 涠洲岛的招牌是椰子冻，夜市摊本地人都认这家，点单照攻略不踩雷。","addr":"南湾夜市"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":2695,"required":false},{"name":"住宿参考","amount":2096,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["轻便雨衣或折叠伞","墨镜与拍照道具","身份证件与手机充电宝","防晒霜与遮阳帽","相机或运动相机","保温水杯与少量现金","常用药品（肠胃药/创可贴）","换洗衣物与外套（早晚温差）"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["饮食注意卫生，海鲜过敏提前告知店家","恶劣天气听从景区安排，不进入未开放区域","涉水项目穿好救生衣，听从工作人员安排","夜间出行结伴，走主路不抄小道"],"faqs":[["到达 北海 的交通方便吗？","推荐先到 北海，再打车或景区直通车前往核心景区；自驾导航直接搜涠洲岛即可。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"]]}',2,'出发这一刻，惊喜已经在路上。','on');
INSERT INTO `travel_route` (`id`,`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES (1169,'德天跨国瀑布纯攻略·臻享版43','guide','广西 · 崇左','water','https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80',5990,2995,2,'德天瀑布 / 明仕田园 / 53号界碑 —— 深度攻略助你玩透德天跨国瀑布精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「德天跨国瀑布」两日慢旅行——水景。崇左酸嘢开胃解腻。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"广西 · 崇左"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴崇左","description":"集合出发，大巴直达德天跨国瀑布，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"德天瀑布","description":"抵达后首游德天瀑布，亚洲第一跨国瀑布，竹筏近观。","addr":"大新县硕龙镇","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐越式卷粉（人均12元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"明仕田园","description":"早起人少，明仕田园精华时段，小桂林田园风光，骑行环线。","addr":"大新县明仕村","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐烤香猪，人均58元，补充体力。","addr":"德天游客中心","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"53号界碑","description":"午后游览53号界碑，中越边境打卡。","addr":"德天景区","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"德天瀑布","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"德天瀑布是德天跨国瀑布最有代表性的看点，亚洲第一跨国瀑布，竹筏近观。攻略把它排进主线，时间留得最足。","notice":"亚洲第一跨国瀑布，竹筏近观。这个点位上午光线最好。","durationMinutes":180,"addr":"大新县硕龙镇"},{"spotId":"S2","name":"明仕田园","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"明仕田园是德天跨国瀑布最有代表性的看点，小桂林田园风光，骑行环线。攻略把它排进主线，时间留得最足。","notice":"小桂林田园风光，骑行环线。这个点位上午光线最好。","durationMinutes":180,"addr":"大新县明仕村"},{"spotId":"S3","name":"53号界碑","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"53号界碑是德天跨国瀑布最有代表性的看点，中越边境打卡。攻略把它排进主线，时间留得最足。","notice":"中越边境打卡。拍照记得留神脚下台阶。","durationMinutes":60,"addr":"德天景区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"越式卷粉（人均12元）","description":"崇左 · 德天跨国瀑布的招牌是越式卷粉，边关小吃本地人都认这家，点单照攻略不踩雷。","addr":"硕龙镇"},{"title":"烤香猪（人均58元）","description":"崇左 · 德天跨国瀑布的招牌是烤香猪，壮乡风味本地人都认这家，点单照攻略不踩雷。","addr":"德天游客中心"},{"title":"酸嘢（人均10元）","description":"崇左 · 德天跨国瀑布的招牌是酸嘢，水果酸摊本地人都认这家，点单照攻略不踩雷。","addr":"明仕田园"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":2695,"required":false},{"name":"住宿参考","amount":2096,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["常用药品（肠胃药/创可贴）","保温水杯与少量现金","少量零食补给","身份证件与手机充电宝","轻便雨衣或折叠伞","舒适徒步鞋（防滑鞋底）","防晒霜与遮阳帽","墨镜与拍照道具"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["饮食注意卫生，海鲜过敏提前告知店家","恶劣天气听从景区安排，不进入未开放区域","贵重物品随身携带，景区人多注意","看好同行老人小孩，走失原地等待"],"faqs":[["当地有什么必吃？","到了 崇左，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["到达 崇左 的交通方便吗？","推荐先到 崇左，再打车或景区直通车前往核心景区；自驾导航直接搜德天跨国瀑布即可。"]]}',2,'把日常调成静音，听风与远方的声音。','on');
INSERT INTO `travel_route` (`id`,`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES (1170,'程阳八寨纯攻略·臻享版44','guide','广西 · 柳州','village','https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80',5990,2995,1,'程阳八寨 / 三江侗天宫 / 窑埠古镇 —— 深度攻略助你玩透程阳八寨精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「程阳八寨」三日深度游——古村落。柳州螺蛳粉袋装正宗。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"广西 · 柳州"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往柳州，抵达后办理入住、熟悉周边环境。","addr":"柳州市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"程阳八寨","description":"下午首站程阳八寨，调整状态进入旅行节奏，风雨桥鼓楼，侗族百家宴。","addr":"柳州市三江县","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游柳州一带氛围拉满，晚餐螺蛳粉人均15元。","addr":"柳州市区","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"三江侗天宫","description":"全天主景点三江侗天宫，侗族文化大观。","addr":"三江县","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐百家宴（人均58元），早点休息。","addr":"程阳八寨","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"窑埠古镇","description":"收官窑埠古镇，百里柳江夜景起点。","addr":"柳州市区","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐打油茶后集合返程，三日旅程圆满。","addr":"程阳八寨","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"程阳八寨","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"程阳八寨是程阳八寨最有代表性的看点，风雨桥鼓楼，侗族百家宴。攻略把它排进主线，时间留得最足。","notice":"风雨桥鼓楼，侗族百家宴。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"柳州市三江县"},{"spotId":"S2","name":"三江侗天宫","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"三江侗天宫是程阳八寨最有代表性的看点，侗族文化大观。攻略把它排进主线，时间留得最足。","notice":"侗族文化大观。拍照记得留神脚下台阶。","durationMinutes":90,"addr":"三江县"},{"spotId":"S3","name":"窑埠古镇","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"窑埠古镇是程阳八寨最有代表性的看点，百里柳江夜景起点。攻略把它排进主线，时间留得最足。","notice":"百里柳江夜景起点。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"柳州市区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"螺蛳粉（人均15元）","description":"柳州 · 程阳八寨的招牌是螺蛳粉，爱民螺蛳粉本地人都认这家，点单照攻略不踩雷。","addr":"柳州市区"},{"title":"百家宴（人均58元）","description":"柳州 · 程阳八寨的招牌是百家宴，程阳八寨本地人都认这家，点单照攻略不踩雷。","addr":"程阳八寨"},{"title":"打油茶（人均20元）","description":"柳州 · 程阳八寨的招牌是打油茶，寨中茶楼本地人都认这家，点单照攻略不踩雷。","addr":"程阳八寨"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":2695,"required":false},{"name":"住宿参考","amount":2096,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["轻便雨衣或折叠伞","墨镜与拍照道具","相机或运动相机","身份证件与手机充电宝","少量零食补给","舒适徒步鞋（防滑鞋底）","换洗衣物与外套（早晚温差）","防晒霜与遮阳帽"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["夜间出行结伴，走主路不抄小道","山区信号弱，提前下载离线地图","饮食注意卫生，海鲜过敏提前告知店家","贵重物品随身携带，景区人多注意"],"faqs":[["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["当地有什么必吃？","到了 柳州，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"]]}',2,'有些风景，照片永远差一点，比如你亲眼看到的那一刻。','on');
INSERT INTO `travel_route` (`id`,`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES (1171,'鼓浪屿纯攻略·臻享版45','guide','福建 · 厦门','sea','https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80',5990,2995,6,'日光岩 / 菽庄花园 / 沙坡尾 —— 深度攻略助你玩透鼓浪屿精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「鼓浪屿」两日慢旅行——海滨。厦门馅饼老字号最正宗。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"福建 · 厦门"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴厦门","description":"集合出发，大巴直达鼓浪屿，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"日光岩","description":"抵达后首游日光岩，全岛最高点看红瓦绿树海景。","addr":"鼓浪屿龙头山路","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐沙茶面（人均28元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"菽庄花园","description":"早起人少，菽庄花园精华时段，四十四桥跨海，钢琴博物馆。","addr":"鼓浪屿港仔后路","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐海蛎煎，人均25元，补充体力。","addr":"八市","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"沙坡尾","description":"午后游览沙坡尾，避风坞文艺街区，猫街涂鸦。","addr":"厦门市思明区","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"日光岩","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"日光岩是鼓浪屿最有代表性的看点，全岛最高点看红瓦绿树海景。攻略把它排进主线，时间留得最足。","notice":"全岛最高点看红瓦绿树海景。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"鼓浪屿龙头山路"},{"spotId":"S2","name":"菽庄花园","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"菽庄花园是鼓浪屿最有代表性的看点，四十四桥跨海，钢琴博物馆。攻略把它排进主线，时间留得最足。","notice":"四十四桥跨海，钢琴博物馆。这个点位上午光线最好。","durationMinutes":120,"addr":"鼓浪屿港仔后路"},{"spotId":"S3","name":"沙坡尾","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"沙坡尾是鼓浪屿最有代表性的看点，避风坞文艺街区，猫街涂鸦。攻略把它排进主线，时间留得最足。","notice":"避风坞文艺街区，猫街涂鸦。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"厦门市思明区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"沙茶面（人均28元）","description":"厦门 · 鼓浪屿的招牌是沙茶面，乌糖沙茶面本地人都认这家，点单照攻略不踩雷。","addr":"民族路"},{"title":"海蛎煎（人均25元）","description":"厦门 · 鼓浪屿的招牌是海蛎煎，莲欢海蛎煎本地人都认这家，点单照攻略不踩雷。","addr":"八市"},{"title":"土笋冻（人均15元）","description":"厦门 · 鼓浪屿的招牌是土笋冻，西门土笋冻本地人都认这家，点单照攻略不踩雷。","addr":"斗西路"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":2695,"required":false},{"name":"住宿参考","amount":2096,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["常用药品（肠胃药/创可贴）","身份证件与手机充电宝","少量零食补给","防晒霜与遮阳帽","舒适徒步鞋（防滑鞋底）","轻便雨衣或折叠伞","相机或运动相机","保温水杯与少量现金"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["涉水项目穿好救生衣，听从工作人员安排","山区信号弱，提前下载离线地图","夜间出行结伴，走主路不抄小道","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["到达 厦门 的交通方便吗？","推荐先到 厦门，再打车或景区直通车前往核心景区；自驾导航直接搜鼓浪屿即可。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"]]}',2,'好运藏在出发的行囊里。','on');
